/* css/tv.css */
/* ============================================
   HOME CINEMA - base rules shared by all screens
   (the look itself is in hc.css, app.css and player.css;
   html font size 1rem = 100px is set in app.css)
   ============================================ */

/* Fonts are self-hosted, see fonts.css */

:root {
    --bg-void: #03060B;
    --text-primary: #EAF6FF;

    /* Focus for TV remote */
    --focus-ring: #3DE8FF;
    --focus-glow: rgba(61, 232, 255, 0.45);

    --font-body: 'Chakra Petch', system-ui, sans-serif;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-body);
    background: var(--bg-void);
    color: var(--text-primary);
    min-height: 100vh;
    line-height: 1.5;
    overflow-x: hidden;

    background-image: url('img/starfield.jpg');
    background-size: cover;
    background-position: center top;
    background-repeat: no-repeat;
    background-attachment: fixed;
}

/* Focus styles for D-pad navigation - CRITICAL for TV */
a:focus,
button:focus,
input:focus,
select:focus {
    outline: none;
    box-shadow: 0 0 0 3px var(--focus-ring), 0 0 20px var(--focus-glow);
    transform: scale(1.02);
    z-index: 10;
}

/* css/hc.css */
/* ============================================
   HOME CINEMA - shared look (header, focus, rows) + Home screen
   Units: 1rem = 100px of the 1920x1080 design (html font-size is
   100vw / 19.2, set in tv.css). Target browser: Samsung Tizen 5.0
   (Chromium 63) - no flexbox `gap`, no min()/max(), no backdrop-filter.
   ============================================ */

:root {
    --accent: #3DE8FF;
    --accent-soft: rgba(61, 232, 255, 0.45);
    --ink: #03060B;
    --panel: #07101B;
    --panel-hi: #0C1C2C;
    --line: #22344A;
    --line-hi: #3A5068;
    --text: #EAF6FF;
    --text-2: #D5E3F0;
    --text-3: #C8D7E5;
    --text-4: #AFC2D4;
    --ok: #5CFFB0;
    --mono: 'JetBrains Mono', Consolas, monospace;
    --sans: 'Chakra Petch', system-ui, sans-serif;
}

body {
    position: relative;
    font-family: var(--sans);
    font-size: 0.26rem;
    background-color: var(--ink);
    color: var(--text);
}

/* Old pages: line up with the new header */
.container {
    position: relative;
    z-index: 1;
    max-width: none;
    padding: 0.48rem 0.96rem 0.96rem;
}

.container--bare {
    padding: 0;
}

/* --------------------------------------------
   Header
   -------------------------------------------- */
.hc-header {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    padding: 0.44rem 0.96rem 0;
}

.hc-logo {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    margin-right: 0.36rem;
    padding: 0.04rem 0.1rem 0.04rem 0;
    color: var(--text);
    text-decoration: none;
    font-size: 0.29rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    white-space: nowrap;
}

.hc-logo svg {
    width: 0.44rem;
    height: 0.44rem;
    margin-right: 0.14rem;
}

.hc-logo i {
    font-style: normal;
    color: var(--accent);
}

.hc-nav {
    display: flex;
    flex-grow: 1;
    min-width: 0;
}

.hc-nav__link {
    height: 0.52rem;
    padding: 0 0.16rem;
    margin-right: 0.04rem;
    display: flex;
    align-items: center;
    flex-shrink: 0;
    font-size: 0.25rem;
    font-weight: 500;
    letter-spacing: 0.06em;
    text-decoration: none;
    white-space: nowrap;
    color: var(--text-3);
    -webkit-clip-path: polygon(0.14rem 0, 100% 0, calc(100% - 0.14rem) 100%, 0 100%);
    clip-path: polygon(0.14rem 0, 100% 0, calc(100% - 0.14rem) 100%, 0 100%);
}

.hc-nav__link svg {
    width: 0.2rem;
    height: 0.2rem;
    margin-right: 0.1rem;
}

.hc-nav__link.is-active {
    color: var(--ink);
    background: var(--accent);
    font-weight: 600;
}

.hc-status {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.12em;
    color: var(--text-3);
    white-space: nowrap;
}


.hc-status > * + * {
    margin-left: 0.18rem;
}

/* No room for the bigger letters: the app says so itself when Webshare is down */
.hc-status__ws {
    display: none;
    align-items: center;
}

.hc-dot {
    width: 0.1rem;
    height: 0.1rem;
    margin-right: 0.1rem;
    border-radius: 50%;
    background: var(--ok);
    box-shadow: 0 0 0.12rem var(--ok);
}

.hc-clock {
    color: var(--text);
    font-size: 0.27rem;
    font-weight: 700;
}

.hc-status__link {
    height: 0.44rem;
    padding: 0 0.09rem;
    letter-spacing: 0.08em;
    display: flex;
    align-items: center;
    font-size: 0.2rem;
    color: var(--text-4);
    text-decoration: none;
    border: 1px solid var(--line);
}

.hc-status__link + .hc-status__link {
    margin-left: 0.08rem;
}

/* --------------------------------------------
   Focus (remote control). tv.css draws a ring with box-shadow + scale;
   clipped shapes cannot show a ring, so the new components light up
   by filling white instead.
   -------------------------------------------- */
.hc-logo:focus,
.hc-nav__link:focus,
.hc-status__link:focus,
.hc-btn:focus,
.hc-frame:focus,
.hc-poster:focus {
    box-shadow: none;
    transform: none;
    outline: none;
}

.hc-logo:focus {
    color: var(--accent);
    text-shadow: 0 0 0.2rem var(--accent);
}

.hc-nav__link:focus,
.hc-status__link:focus {
    color: var(--ink);
    background: var(--text);
    border-color: var(--text);
}

/* --------------------------------------------
   Buttons with cut corners
   -------------------------------------------- */
.hc-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    height: 0.76rem;
    padding: 0 0.44rem;
    border: 0;
    cursor: pointer;
    font-family: var(--sans);
    font-size: 0.28rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-decoration: none;
    white-space: nowrap;
    color: var(--ink);
    background: var(--accent);
    -webkit-clip-path: polygon(0.2rem 0, 100% 0, 100% calc(100% - 0.2rem), calc(100% - 0.2rem) 100%, 0 100%, 0 0.2rem);
    clip-path: polygon(0.2rem 0, 100% 0, 100% calc(100% - 0.2rem), calc(100% - 0.2rem) 100%, 0 100%, 0 0.2rem);
}

.hc-btn svg {
    width: 0.24rem;
    height: 0.24rem;
}

.hc-btn svg + span {
    margin-left: 0.14rem;
}

.hc-btn--ghost {
    color: var(--text);
    background: var(--panel);
    box-shadow: inset 0 0 0 0.02rem var(--line-hi);
}

.hc-btn--icon {
    width: 0.76rem;
    padding: 0;
}

.hc-btn.is-on {
    color: var(--accent);
    box-shadow: inset 0 0 0 0.02rem var(--accent);
}

.hc-btn:focus {
    color: var(--ink);
    background: var(--text);
    box-shadow: none;
}

/* Glow has to sit on an unclipped wrapper */
.hc-glow {
    display: flex;
    flex-shrink: 0;
}

/* --------------------------------------------
   Framed card: 2px frame that lights up on focus
   -------------------------------------------- */
.hc-frame {
    display: block;
    flex-shrink: 0;
    padding: 0.02rem;
    background: var(--line);
    color: var(--text);
    text-decoration: none;
    -webkit-clip-path: polygon(0 0, calc(100% - 0.26rem) 0, 100% 0.26rem, 100% 100%, 0.26rem 100%, 0 calc(100% - 0.26rem));
    clip-path: polygon(0 0, calc(100% - 0.26rem) 0, 100% 0.26rem, 100% 100%, 0.26rem 100%, 0 calc(100% - 0.26rem));
}

.hc-frame__in {
    display: block;
    background: var(--panel);
    -webkit-clip-path: polygon(0 0, calc(100% - 0.25rem) 0, 100% 0.25rem, 100% 100%, 0.25rem 100%, 0 calc(100% - 0.25rem));
    clip-path: polygon(0 0, calc(100% - 0.25rem) 0, 100% 0.25rem, 100% 100%, 0.25rem 100%, 0 calc(100% - 0.25rem));
}

.hc-frame:focus {
    background: var(--accent);
}

.hc-frame:focus .hc-frame__in {
    background: var(--panel-hi);
}

/* --------------------------------------------
   Section heading + horizontal row
   -------------------------------------------- */
.hc-section {
    position: relative;
    z-index: 1;
    padding-left: 0.96rem;
    margin-top: 0.4rem;
}

.hc-section__head {
    display: flex;
    align-items: center;
    margin-bottom: 0.06rem;
}

.hc-section__bar {
    width: 0.34rem;
    height: 0.03rem;
    margin-right: 0.18rem;
    background: var(--accent);
}

.hc-section__title {
    margin: 0;
    font-size: 0.31rem;
    font-weight: 600;
    letter-spacing: 0.14em;
}

.hc-section__count {
    margin-left: 0.18rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--text-4);
}

/* Padding leaves room for the focus glow, negative margin gives it back */
.hc-row {
    position: relative;
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    padding: 0.14rem 0.96rem 0.2rem 0.2rem;
    margin-left: -0.2rem;
}

.hc-row::-webkit-scrollbar {
    display: none;
}

/* Poster in a row */
.hc-poster {
    display: block;
    flex-shrink: 0;
    width: 2.12rem;
    margin-right: 0.18rem;
    padding: 0.02rem;
    background: transparent;
    text-decoration: none;
    -webkit-clip-path: polygon(0 0, calc(100% - 0.22rem) 0, 100% 0.22rem, 100% 100%, 0 100%);
    clip-path: polygon(0 0, calc(100% - 0.22rem) 0, 100% 0.22rem, 100% 100%, 0 100%);
}

.hc-poster img,
.hc-poster__blank {
    display: block;
    width: 2.08rem;
    height: 3.12rem;
    object-fit: cover;
    background: var(--panel);
    -webkit-clip-path: polygon(0 0, calc(100% - 0.21rem) 0, 100% 0.21rem, 100% 100%, 0 100%);
    clip-path: polygon(0 0, calc(100% - 0.21rem) 0, 100% 0.21rem, 100% 100%, 0 100%);
}

.hc-poster__blank {
    display: flex;
    align-items: flex-end;
    padding: 0.16rem;
    font-size: 0.25rem;
    font-weight: 600;
    line-height: 1.2;
    color: var(--text-2);
}

.hc-poster:focus {
    background: var(--accent);
}

/* Tip rows keep a poster's height while they fill, so nothing jumps */
.hc-tips .hc-row {
    min-height: 3.5rem;
}

.hc-tips__wait {
    align-self: center;
    font-family: var(--mono);
    font-size: 0.21rem;
    letter-spacing: 0.14em;
    color: var(--text-4);
}

.hc-poster-wrap {
    display: flex;
    flex-shrink: 0;
}

/* No glow filter on focus: it made moving around stutter on the TV.
   The accent frame alone marks the focused poster. */

/* --------------------------------------------
   Home: background layers
   -------------------------------------------- */
.hc-home-bg {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 10.8rem;
    overflow: hidden;
    z-index: 0;
    pointer-events: none;
}

.hc-home-bg__art {
    position: absolute;
    left: 0;
    top: -1.5rem;
    width: 100%;
    height: 10.74rem;
    object-fit: cover;
    -webkit-mask-image: linear-gradient(to bottom, #000 58%, transparent 86%);
    mask-image: linear-gradient(to bottom, #000 58%, transparent 86%);
}

.hc-home-bg__top {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 1.8rem;
    background: linear-gradient(to bottom, rgba(3, 6, 11, 0.92), rgba(3, 6, 11, 0));
}

/* Not in the mockup: real backdrops are not composed for text on the left */
.hc-home-bg__left {
    position: absolute;
    left: 0;
    top: 0;
    width: 62%;
    height: 100%;
    background: linear-gradient(to right, rgba(3, 6, 11, 0.9), rgba(3, 6, 11, 0.55) 55%, rgba(3, 6, 11, 0));
}

.hc-home-bg__hud {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
}

/* --------------------------------------------
   Home: hero
   -------------------------------------------- */
.hc-hero {
    position: relative;
    z-index: 1;
    width: 8rem;
    min-height: 4.82rem;
    margin: 0.72rem 0 0 0.96rem;
}

.hc-hero > * + * {
    margin-top: 0.2rem;
}

.hc-kicker {
    display: block;
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.2em;
    color: var(--accent);
}

.hc-hero__title {
    margin-bottom: 0;
    font-size: 1.36rem;
    font-weight: 700;
    line-height: 0.95;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    text-shadow: 0 0 0.4rem rgba(61, 232, 255, 0.35);
}

.hc-hero__title--m {
    font-size: 0.96rem;
    line-height: 1;
}

.hc-hero__title--s {
    font-size: 0.68rem;
    line-height: 1.05;
    letter-spacing: 0.04em;
}

.hc-hero__meta {
    font-family: var(--mono);
    font-size: 0.23rem;
    font-weight: 500;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-3);
}

.hc-hero__meta i {
    font-style: normal;
    margin: 0 0.18rem;
    color: var(--accent);
}

.hc-hero__plot {
    max-width: 6.8rem;
    font-size: 0.28rem;
    line-height: 1.5;
    color: var(--text-2);
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
}

.hc-hero__actions {
    display: flex;
    align-items: center;
    padding-top: 0.12rem;
}

.hc-hero__actions > * + * {
    margin-left: 0.18rem;
}

/* --------------------------------------------
   Home: continue watching cards
   -------------------------------------------- */
.hc-cont {
    display: block;
    flex-shrink: 0;
    width: 4.04rem;
    margin-right: 0.26rem;
    color: var(--text);
    text-decoration: none;
}

.hc-cont:focus {
    box-shadow: none;
    transform: none;
    outline: none;
}

.hc-cont:focus .hc-frame {
    background: var(--accent);
}

.hc-cont:focus .hc-cont__left {
    color: var(--accent);
}

.hc-cont__panel {
    display: block;
    position: relative;
    height: 1.96rem;
    overflow: hidden;
    background: linear-gradient(135deg, #0C1C2C, #07101B 70%);
}

.hc-cont__art {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Darker at the bottom and the right so the title and % stay readable */
.hc-cont__shade {
    position: absolute;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(to top, rgba(3, 6, 11, 0.92), rgba(3, 6, 11, 0.35) 60%, rgba(3, 6, 11, 0.1));
}

.hc-cont__title {
    position: absolute;
    left: 0.34rem;
    right: 0.8rem;
    bottom: 0.26rem;
    font-size: 0.28rem;
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
}

.hc-cont__pct {
    position: absolute;
    right: 0.14rem;
    top: 0.34rem;
    padding: 0.04rem 0.08rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 700;
    color: var(--accent);
    background: rgba(3, 6, 11, 0.8);
}

.hc-cont__bar {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 0.05rem;
    background: rgba(255, 255, 255, 0.18);
}

.hc-cont__bar i {
    display: block;
    height: 100%;
    background: var(--accent);
    box-shadow: 0 0 0.12rem var(--accent);
}

.hc-cont__left {
    display: block;
    padding: 0.1rem 0.02rem 0;
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.06em;
    color: var(--text-4);
}

.hc-home-end {
    height: 0.6rem;
}

/* --------------------------------------------
   Film lists menu (/movies)
   -------------------------------------------- */
.hc-page-head {
    margin-bottom: 0.36rem;
}

.hc-page-head h1 {
    margin-top: 0.08rem;
    font-size: 0.44rem;
    font-weight: 600;
    letter-spacing: 0.1em;
}

.hc-tiles {
    display: flex;
    flex-wrap: wrap;
    margin: 0 -0.13rem;
}

.hc-tile {
    width: 5.5rem;
    margin: 0 0.13rem 0.26rem;
}

.hc-tile .hc-frame__in {
    display: flex;
    flex-direction: column;
    justify-content: center;
    height: 1.4rem;
    padding: 0 0.36rem;
}

.hc-tile__name {
    font-size: 0.32rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.hc-tile__sub {
    margin-top: 0.08rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    letter-spacing: 0.1em;
    color: var(--text-4);
}

.hc-tile:focus .hc-tile__sub {
    color: var(--accent);
}

/* Tiles with a picture: dimmed behind the text, full on focus.
   The shade keeps the text on the left readable. */
.hc-tile--art .hc-frame__in {
    position: relative;
    overflow: hidden;
}

.hc-tile__art {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: auto;
}

/* The whole picture sits on the right; its dark left part fades into
   the panel under the text. No change on focus: the TV redraws a
   fading picture inside the clipped frame with a flicker. */
.hc-tile__shade {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, var(--panel) 0%, var(--panel) 36%, rgba(7, 16, 27, 0.55) 52%, rgba(7, 16, 27, 0) 66%);
}

.hc-tile--art:focus .hc-tile__shade {
    background: linear-gradient(90deg, var(--panel-hi) 0%, var(--panel-hi) 36%, rgba(12, 28, 44, 0.55) 52%, rgba(12, 28, 44, 0) 66%);
}

.hc-tile--art .hc-tile__name,
.hc-tile--art .hc-tile__sub {
    position: relative;
    text-shadow: 0 0 0.12rem #03060B, 0 0 0.04rem #03060B;
}

/* --------------------------------------------
   Shared: focus reset for the newer components, back link, text fields
   -------------------------------------------- */
.hc-back:focus,
.hc-stream:focus,
.hc-filter:focus,
.hc-field__input:focus {
    box-shadow: none;
    transform: none;
    outline: none;
}

.hc-back {
    display: inline-flex;
    align-items: center;
    justify-content: flex-start;
    width: auto;
    height: 0.44rem;
    border-radius: 0;
    background: transparent;
    white-space: nowrap;
    padding: 0 0.14rem 0 0.06rem;
    font-family: var(--mono);
    font-size: 0.22rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--text-3);
    text-decoration: none;
}

.hc-back svg {
    width: 0.2rem;
    height: 0.2rem;
    margin-right: 0.1rem;
}

.hc-back:focus {
    color: var(--ink);
    background: var(--text);
}

.hc-field {
    display: block;
    margin-top: 0.26rem;
}

.hc-field__label {
    display: block;
    margin-bottom: 0.1rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--accent);
}

.hc-field__input {
    display: block;
    width: 100%;
    height: 0.72rem;
    padding: 0 0.22rem;
    border: 0.02rem solid var(--line-hi);
    border-radius: 0;
    background: rgba(3, 6, 11, 0.7);
    color: var(--text);
    font-family: var(--sans);
    font-size: 0.31rem;
    font-weight: 500;
    letter-spacing: 0.04em;
}

.hc-field__input:focus {
    border-color: var(--accent);
    background: var(--panel-hi);
    box-shadow: 0 0 0.2rem var(--accent-soft);
}

/* --------------------------------------------
   Login
   -------------------------------------------- */
.hc-login-hud {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
}

.hc-login {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    min-height: 100vh;
    padding: 0 1.6rem 0 1.6rem;
}

.hc-login__brand {
    width: 7.4rem;
    flex-shrink: 0;
}

.hc-login__mark {
    display: block;
    width: 1.1rem;
    height: 1.1rem;
    margin-bottom: 0.4rem;
    -webkit-filter: drop-shadow(0 0 0.18rem var(--accent-soft));
    filter: drop-shadow(0 0 0.18rem var(--accent-soft));
}

.hc-login__title {
    margin: 0.2rem 0 0;
    font-size: 1.28rem;
    font-weight: 700;
    line-height: 0.98;
    letter-spacing: 0.08em;
    text-shadow: 0 0 0.4rem rgba(61, 232, 255, 0.35);
}

.hc-login__title i {
    font-style: normal;
    color: var(--accent);
}

.hc-login__text {
    max-width: 5.6rem;
    margin-top: 0.34rem;
    font-size: 0.28rem;
    line-height: 1.5;
    color: var(--text-2);
}

.hc-login__form {
    flex-grow: 1;
    margin-left: 2rem;
    -webkit-filter: drop-shadow(0 0 0.3rem rgba(61, 232, 255, 0.18));
    filter: drop-shadow(0 0 0.3rem rgba(61, 232, 255, 0.18));
}

.hc-login__frame {
    background: var(--line-hi);
}

.hc-login__panel {
    padding: 0.5rem 0.56rem 0.46rem;
    background: #07101B;
}

.hc-login__heading {
    margin: 0.08rem 0 0.1rem;
    font-size: 0.44rem;
    font-weight: 600;
    letter-spacing: 0.1em;
}

.hc-login__error {
    margin-top: 0.22rem;
    padding: 0.14rem 0.18rem;
    border-left: 0.04rem solid #FF5C7A;
    background: rgba(255, 92, 122, 0.12);
    font-size: 0.25rem;
    color: #FFC2CD;
}

.hc-login__submit {
    width: 100%;
    margin-top: 0.4rem;
    text-transform: uppercase;
}

.hc-login__submit:disabled {
    opacity: 0.6;
}

.hc-login__note {
    margin-top: 0.26rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    letter-spacing: 0.04em;
    line-height: 1.5;
    color: var(--text-4);
}

/* --------------------------------------------
   Film detail + stream picker (/streams)
   -------------------------------------------- */
.hc-detail-bg {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    pointer-events: none;
}

.hc-detail-bg__art {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 0.85;
}

.hc-detail-bg__shade {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, rgba(3, 6, 11, 0.72), rgba(3, 6, 11, 0.5) 40%, rgba(3, 6, 11, 0.3));
}

.hc-detail {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: flex-start;
    padding: 0.8rem 0.96rem 0.8rem;
}

.hc-detail__film {
    position: -webkit-sticky;
    position: sticky;
    top: 0.8rem;
    width: 6rem;
    flex-shrink: 0;
    margin-right: 0.64rem;
    padding-right: 0.64rem;
    border-right: 1px solid #24364A;
    box-sizing: content-box;
}

.hc-detail__film > * + * {
    margin-top: 0.24rem;
}

.hc-detail__top {
    display: flex;
    align-items: stretch;
}

.hc-detail__poster {
    display: block;
    flex-shrink: 0;
    margin-right: 0.3rem;
    padding: 0.02rem;
    background: var(--accent);
    -webkit-clip-path: polygon(0 0, calc(100% - 0.28rem) 0, 100% 0.28rem, 100% 100%, 0.28rem 100%, 0 calc(100% - 0.28rem));
    clip-path: polygon(0 0, calc(100% - 0.28rem) 0, 100% 0.28rem, 100% 100%, 0.28rem 100%, 0 calc(100% - 0.28rem));
}

.hc-detail__poster img {
    display: block;
    width: 2.2rem;
    height: 3.3rem;
    object-fit: cover;
    -webkit-clip-path: polygon(0 0, calc(100% - 0.27rem) 0, 100% 0.27rem, 100% 100%, 0.27rem 100%, 0 calc(100% - 0.27rem));
    clip-path: polygon(0 0, calc(100% - 0.27rem) 0, 100% 0.27rem, 100% 100%, 0.27rem 100%, 0 calc(100% - 0.27rem));
}

.hc-facts {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    flex-grow: 1;
    min-width: 0;
    margin: 0;
    font-family: var(--mono);
    letter-spacing: 0.08em;
}

.hc-facts > div {
    padding-bottom: 0.12rem;
    border-bottom: 1px solid #24364A;
}

.hc-facts > div + div {
    margin-top: 0.12rem;
}

.hc-facts > div:last-child {
    padding-bottom: 0;
    border-bottom: 0;
}

.hc-facts dt {
    font-size: 0.2rem;
    font-weight: 500;
    color: var(--accent);
}

.hc-facts dd {
    margin: 0.04rem 0 0;
    font-size: 0.23rem;
    font-weight: 500;
    line-height: 1.3;
    text-transform: uppercase;
}

.hc-detail__title {
    margin-bottom: 0;
    font-size: 1.04rem;
    font-weight: 700;
    line-height: 0.95;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    text-shadow: 0 0 0.4rem rgba(61, 232, 255, 0.35);
    word-wrap: break-word;
}

.hc-detail__title--m {
    font-size: 0.64rem;
    line-height: 1;
    letter-spacing: 0.04em;
}

.hc-detail__title--s {
    font-size: 0.44rem;
    line-height: 1.08;
    letter-spacing: 0.03em;
}

.hc-detail__plot {
    font-size: 0.26rem;
    line-height: 1.5;
    color: var(--text-2);
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 5;
    overflow: hidden;
}

.hc-crew__list {
    display: flex;
    flex-wrap: wrap;
    margin: 0.1rem -0.05rem 0;
}

.hc-crew__list span {
    margin: 0.05rem;
    padding: 0.08rem 0.15rem;
    border: 1px solid #2E4560;
    background: rgba(7, 16, 27, 0.7);
    font-size: 0.23rem;
    color: var(--text-2);
}

.hc-detail__streams {
    flex-grow: 1;
    min-width: 0;
    padding-top: 0.16rem;
}

.hc-detail__actions {
    display: flex;
    margin-top: 0.3rem;
}

.hc-pick-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
}

.hc-pick-head h2 {
    margin: 0.08rem 0 0;
    font-size: 0.44rem;
    font-weight: 600;
    letter-spacing: 0.1em;
}

.hc-pick-head__count {
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.12em;
    color: var(--text-4);
}

.hc-filters {
    display: flex;
    margin-top: 0.24rem;
}

.hc-filter {
    height: 0.5rem;
    padding: 0 0.16rem;
    margin-right: 0.08rem;
    border: 1px solid #2E4560;
    border-radius: 0;
    background: rgba(7, 16, 27, 0.7);
    color: var(--text-2);
    font-family: var(--sans);
    font-size: 0.23rem;
    font-weight: 500;
    letter-spacing: 0.05em;
    white-space: nowrap;
    cursor: pointer;
}

.hc-filter.is-on {
    border-color: var(--accent);
    color: var(--accent);
    font-weight: 600;
}

.hc-filter:focus {
    border-color: var(--text);
    background: var(--text);
    color: var(--ink);
    font-weight: 600;
}

.hc-streams {
    margin-top: 0.24rem;
}

.hc-stream {
    display: block;
    margin-bottom: 0.14rem;
    color: var(--text);
    text-decoration: none;
}

/* Focus is shown by the accent frame below (no filter: too slow on the TV) */

.hc-stream:focus .hc-frame {
    background: var(--accent);
}

.hc-stream:focus .hc-frame__in {
    background: var(--panel-hi);
}

.hc-stream__in {
    display: flex;
    align-items: center;
    padding: 0.18rem 0.28rem;
}

.hc-stream__no {
    width: 0.24rem;
    margin-right: 0.24rem;
    flex-shrink: 0;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    color: var(--text-4);
}

.hc-stream__res {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1.04rem;
    height: 0.56rem;
    margin-right: 0.26rem;
    flex-shrink: 0;
    font-size: 0.3rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    background: #16283C;
    -webkit-clip-path: polygon(0.12rem 0, 100% 0, calc(100% - 0.12rem) 100%, 0 100%);
    clip-path: polygon(0.12rem 0, 100% 0, calc(100% - 0.12rem) 100%, 0 100%);
}

.hc-stream__res--long {
    font-size: 0.27rem;
    letter-spacing: 0.03em;
}

.hc-stream:focus .hc-stream__res {
    background: var(--accent);
    color: var(--ink);
}

.hc-stream__main {
    flex-grow: 1;
    min-width: 0;
    margin-right: 0.24rem;
}

.hc-stream__label,
.hc-stream__file {
    display: block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.hc-stream__label {
    font-size: 0.27rem;
    font-weight: 600;
    letter-spacing: 0.04em;
}

.hc-stream__file {
    margin-top: 0.06rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    color: var(--text-4);
}

.hc-stream__tags {
    display: flex;
    flex-shrink: 0;
}

.hc-stream__tags span {
    margin-left: 0.08rem;
    padding: 0.06rem 0.1rem;
    border: 1px solid var(--line-hi);
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.08em;
    white-space: nowrap;
    color: var(--text-2);
}

.hc-stream__tags span.is-ok {
    border-color: var(--ok);
    color: var(--ok);
}

.hc-stream__size {
    width: 0.96rem;
    flex-shrink: 0;
    text-align: right;
    font-family: var(--mono);
    font-size: 0.22rem;
    font-weight: 500;
    white-space: nowrap;
    color: var(--text-3);
}

.hc-pick-note,
.hc-pick-empty {
    margin-top: 0.2rem;
    font-family: var(--mono);
    font-size: 0.21rem;
    letter-spacing: 0.04em;
    line-height: 1.5;
    color: var(--text-4);
}

.hc-pick-empty {
    font-size: 0.25rem;
    color: var(--text-2);
}

/* --------------------------------------------
   Search: on-screen keyboard (left) + film results (right)
   -------------------------------------------- */
.hc-search-bg {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: var(--ink) url(img/starfield.jpg) center / cover no-repeat;
}

.hc-search-bg:after {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(3, 6, 11, 0.82);
}

.hc-search__rule {
    position: fixed;
    left: 7rem;
    top: 0.6rem;
    bottom: 0.6rem;
    width: 1px;
    background: var(--line);
}

.hc-search__left {
    position: fixed;
    z-index: 1;
    left: 0.96rem;
    top: 0.5rem;
    width: 5.48rem;
}

.hc-search__left .hc-kicker {
    margin-top: 0.3rem;
}

.hc-search__box {
    display: flex;
    align-items: center;
    height: 0.84rem;
    margin-top: 0.16rem;
    padding: 0 0.22rem;
    border: 0.02rem solid var(--accent);
    background: var(--panel);
    overflow: hidden;
}

.hc-search__box svg {
    flex-shrink: 0;
    width: 0.3rem;
    height: 0.3rem;
    margin-right: 0.16rem;
    color: var(--accent);
}

.hc-search__text {
    font-size: 0.34rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    white-space: pre;
    color: var(--text);
}

.hc-search__text.is-empty {
    font-size: 0.29rem;
    font-weight: 500;
    color: var(--text-4);
}

.hc-search__caret {
    flex-shrink: 0;
    width: 0.03rem;
    height: 0.4rem;
    margin-left: 0.04rem;
    background: var(--accent);
    -webkit-animation: hc-caret 1s steps(1) infinite;
    animation: hc-caret 1s steps(1) infinite;
}

@-webkit-keyframes hc-caret { 50% { opacity: 0; } }
@keyframes hc-caret { 50% { opacity: 0; } }

.hc-keys {
    display: flex;
    flex-wrap: wrap;
    margin: 0.22rem -0.08rem 0 0;
}

.hc-key {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 0.7rem;
    height: 0.64rem;
    margin: 0 0.08rem 0.08rem 0;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 0;
    background: var(--panel);
    color: var(--text);
    font-family: var(--sans);
    font-size: 0.31rem;
    font-weight: 600;
    cursor: pointer;
}

.hc-key--wide {
    width: 1.48rem;
    font-size: 0.23rem;
    letter-spacing: 0.1em;
}

.hc-key--space {
    width: 2.26rem;
    font-size: 0.23rem;
    letter-spacing: 0.1em;
}

.hc-key:focus,
.hc-chip:focus {
    outline: none;
    transform: none;
    border-color: var(--accent);
    background: var(--accent);
    color: var(--ink);
    box-shadow: 0 0 0.2rem rgba(61, 232, 255, 0.6);
}

.hc-recent {
    margin-top: 0.22rem;
}

.hc-recent__label {
    display: block;
    margin-bottom: 0.1rem;
    font-family: var(--mono);
    font-size: 0.2rem;
    letter-spacing: 0.16em;
    color: var(--text-4);
}

.hc-recent__list {
    display: flex;
    flex-wrap: wrap;
    max-height: 1.08rem;
    overflow: hidden;
}

.hc-chip {
    max-width: 2.6rem;
    height: 0.46rem;
    margin: 0 0.08rem 0.08rem 0;
    padding: 0 0.16rem;
    border: 1px solid var(--line);
    border-radius: 0;
    background: transparent;
    color: var(--text-2);
    font-family: var(--sans);
    font-size: 0.24rem;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: pointer;
}

.hc-search__right {
    position: relative;
    z-index: 1;
    margin-left: 7.64rem;
    padding: 0.94rem 0.6rem 0.8rem 0;
    min-height: 100vh;
}

.hc-search__head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-top: 0.1rem;
}

.hc-search__head h1 {
    margin: 0;
    min-width: 0;
    font-size: 0.4rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.hc-search__count {
    flex-shrink: 0;
    margin-left: 0.3rem;
    font-family: var(--mono);
    font-size: 0.21rem;
    letter-spacing: 0.14em;
    color: var(--text-4);
}

.hc-search__note {
    margin-top: 0.4rem;
    max-width: 8rem;
    font-size: 0.29rem;
    line-height: 1.5;
    color: var(--text-3);
}

.hc-search__top {
    display: flex;
    margin-top: 0.3rem;
