/* css/app.css */
/* Things only the TV app needs, on top of the shared look (tv.css, hc.css) */

/* The app always runs at 1920x1080: 1rem = 100px */
html {
    font-size: 100px;
    scroll-behavior: auto;
}

/* While a film plays the TV's own player draws underneath the page,
   so the page must be see-through */
body.is-playing,
html.is-playing {
    background: transparent !important;
}

body.is-playing #shell {
    display: none;
}

#player {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
}

#av,
#video {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
}

#video {
    background: #000;
}

.app-loading {
    padding: 2rem 0.96rem;
}

/* Starfield: tv.css pins it with background-attachment: fixed, which makes
   the TV repaint the whole page on every scroll. Draw it on its own fixed
   layer instead. Hidden while a film plays (the video is under the page). */
body {
    background-image: none;
    background-attachment: scroll;
}

body::before {
    content: '';
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background: url('img/starfield.jpg') center top / cover no-repeat;
    -webkit-transform: translateZ(0);
    transform: translateZ(0);
    pointer-events: none;
}

body.is-playing::before {
    display: none;
}

/* css/player.css */
/* ============================================
   HOME CINEMA - player (TV app)
   Same rules as streaming-web/static/css/player.css, kept inside #player
   so they do not touch the rest of the app. 1rem = 100px.
   ============================================ */

#player {
    --panel: #07101B;
    --panel-hi: #0C1C2C;
    --line: #22344A;
    --line-hi: #3A5068;
    --text-2: #D5E3F0;
    --text-3: #C8D7E5;
    --text-4: #AFC2D4;
    font-family: var(--sans);
    font-size: 0.26rem;
    color: var(--text);
}

#player * {
    box-sizing: border-box;
}

#player button {
    margin: 0;
    border-radius: 0;
    font-family: var(--sans);
    cursor: pointer;
}

#player button:focus,
.pl-bar:focus {
    outline: none;
}

.pl object {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
}

.pl {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
}

.pl video {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    background: #000;
}

/* --------------------------------------------
   Subtitles (drawn by the page, not by the browser)
   -------------------------------------------- */
.pl-sub {
    position: absolute;
    left: 10%;
    width: 80%;
    bottom: 0.9rem;
    text-align: center;
    pointer-events: none;
    transition: bottom 0.2s;
}

.pl-sub p {
    margin: 0;
    font-size: 0.46rem;
    font-weight: 600;
    line-height: 1.3;
    color: #FFFFFF;
    white-space: pre-line;
    text-shadow: 0 0.02rem 0.1rem #000, 0 0 0.03rem #000, 0 0 0.03rem #000;
}

.pl.is-ui .pl-sub {
    bottom: 3rem;
}

.pl.is-panel .pl-sub {
    left: 0.96rem;
    width: 11.4rem;
}

/* --------------------------------------------
   Short messages in the middle of the picture
   -------------------------------------------- */
.pl-toast,
.pl-wait {
    position: absolute;
    left: 50%;
    top: 44%;
    -webkit-transform: translate(-50%, -50%);
    transform: translate(-50%, -50%);
    padding: 0.22rem 0.44rem;
    border: 1px solid var(--line-hi);
    background: rgba(5, 12, 21, 0.9);
    text-align: center;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
}

.pl-toast.is-on,
.pl-wait.is-on {
    opacity: 1;
}

.pl-toast b {
    display: block;
    font-family: var(--mono);
    font-size: 0.44rem;
    font-weight: 700;
}

.pl-toast span {
    display: block;
    margin-top: 0.06rem;
    font-family: var(--mono);
    font-size: 0.22rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--accent);
}

.pl-toast span:empty {
    display: none;
}

.pl-wait {
    font-family: var(--mono);
    font-size: 0.24rem;
    font-weight: 500;
    letter-spacing: 0.2em;
    color: var(--accent);
}

/* --------------------------------------------
   Controls layer
   -------------------------------------------- */
.pl-ui {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.25s;
}

.pl.is-ui .pl-ui {
    opacity: 1;
    pointer-events: auto;
}

.pl.is-ui {
    cursor: default;
}

.pl {
    cursor: none;
}

.pl-shade {
    position: absolute;
    left: 0;
    width: 100%;
    pointer-events: none;
}

.pl-shade--top {
    top: 0;
    height: 2.2rem;
    background: linear-gradient(to bottom, rgba(3, 6, 11, 0.9), rgba(3, 6, 11, 0));
}

.pl-shade--bottom {
    bottom: 0;
    height: 4.2rem;
    background: linear-gradient(to top, rgba(3, 6, 11, 0.96) 30%, rgba(3, 6, 11, 0));
}

.pl-hud {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
}

.pl-head {
    position: absolute;
    left: 0.96rem;
    right: 0.96rem;
    top: 0.6rem;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.pl-head__text {
    min-width: 0;
    padding-right: 0.4rem;
}

.pl-kicker {
    display: block;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.2em;
    color: var(--accent);
}

.pl-title {
    display: block;
    margin-top: 0.08rem;
    font-size: 0.46rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.pl-info {
    display: block;
    margin-top: 0.08rem;
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.1em;
    color: var(--text-3);
}

/* Buttons: resting = dark, focused = white, switched on = accent */
.pl-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    height: 0.64rem;
    padding: 0 0.28rem;
    border: 0.015rem solid var(--line-hi);
    background: rgba(7, 16, 27, 0.85);
    color: var(--text);
    font-size: 0.25rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    white-space: nowrap;
}

.pl-btn svg {
    width: 0.3rem;
    height: 0.3rem;
}

.pl-btn.is-on {
    border-color: var(--accent);
    color: var(--accent);
}

.pl-btn:focus {
    border-color: var(--text);
    background: var(--text);
    color: var(--ink);
}

.pl-btn--cut {
    border: 0;
    -webkit-clip-path: polygon(0.18rem 0, 100% 0, 100% calc(100% - 0.18rem), calc(100% - 0.18rem) 100%, 0 100%, 0 0.18rem);
    clip-path: polygon(0.18rem 0, 100% 0, 100% calc(100% - 0.18rem), calc(100% - 0.18rem) 100%, 0 100%, 0 0.18rem);
}

.pl-btn--cut:not(:focus) {
    background: #16283C;
}

.pl-btn--sq {
    width: 0.76rem;
    height: 0.76rem;
    padding: 0;
}

.pl-btn--close {
    width: 0.64rem;
    height: 0.64rem;
    padding: 0;
}

.pl-btn--close svg {
    width: 0.24rem;
    height: 0.24rem;
}

.pl-btn--play {
    width: 1.04rem;
    height: 0.92rem;
    padding: 0;
    margin: 0 0.16rem;
}

.pl-btn--play svg {
    width: 0.34rem;
    height: 0.34rem;
}

.pl-btn--play .ico-play,
.pl.is-paused .pl-btn--play .ico-pause {
    display: none;
}

.pl.is-paused .pl-btn--play .ico-play {
    display: block;
}

.pl-foot {
    position: absolute;
    left: 0.96rem;
    right: 0.96rem;
    bottom: 0.64rem;
}

.pl-time {
    display: flex;
    align-items: center;
}

.pl-time__now,
.pl-time__left {
    flex-shrink: 0;
    font-family: var(--mono);
    font-size: 0.27rem;
    font-weight: 700;
}

.pl-time__left {
    font-weight: 500;
    color: var(--text-3);
}

.pl-bar {
    position: relative;
    flex-grow: 1;
    height: 0.4rem;
    margin: 0 0.24rem;
    cursor: pointer;
}

/* Bigger target for the remote's pointer than the thin line itself */
.pl-bar:before {
    content: '';
    position: absolute;
    left: 0;
    width: 100%;
    top: -0.2rem;
    height: 0.8rem;
}

.pl-bar__tip {
    position: absolute;
    top: -0.44rem;
    padding: 0.04rem 0.1rem;
    -webkit-transform: translateX(-50%);
    transform: translateX(-50%);
    background: var(--text);
    color: var(--ink);
    font-family: var(--mono);
    font-size: 0.22rem;
    font-weight: 700;
    white-space: nowrap;
    pointer-events: none;
    display: none;
}

.pl-bar.is-hover .pl-bar__tip {
    display: block;
}

.pl-bar.is-hover .pl-bar__hint {
    display: none;
}

.pl-bar__track,
.pl-bar__fill {
    position: absolute;
    left: 0;
    top: 0.17rem;
    height: 0.06rem;
}

.pl-bar__track {
    width: 100%;
    background: rgba(255, 255, 255, 0.2);
}

.pl-bar__fill {
    width: 0;
    background: var(--accent);
    box-shadow: 0 0 0.14rem var(--accent);
}

.pl-bar__thumb {
    position: absolute;
    left: 0;
    top: 0.07rem;
    width: 0.1rem;
    height: 0.26rem;
    margin-left: -0.05rem;
    background: var(--text);
    box-shadow: 0 0 0.14rem var(--accent);
}

.pl-bar:focus .pl-bar__track {
    top: 0.15rem;
    height: 0.1rem;
    background: rgba(255, 255, 255, 0.34);
}

.pl-bar:focus .pl-bar__fill {
    top: 0.15rem;
    height: 0.1rem;
}

.pl-bar:focus .pl-bar__thumb {
    top: 0;
    width: 0.16rem;
    height: 0.4rem;
    margin-left: -0.08rem;
    background: var(--accent);
    box-shadow: 0 0 0.22rem var(--accent);
}

.pl-bar__hint {
    position: absolute;
    left: 0;
    width: 100%;
    top: -0.24rem;
    text-align: center;
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    color: var(--accent);
    display: none;
}

.pl-bar:focus .pl-bar__hint {
    display: block;
}

.pl-controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.26rem;
}

.pl-controls__group {
    display: flex;
    align-items: center;
}

.pl-controls__group--right .pl-btn {
    margin-left: 0.12rem;
}

/* --------------------------------------------
   Subtitle panel
   -------------------------------------------- */
.pl-panel {
    position: absolute;
    right: 0.96rem;
    bottom: 2.36rem;
    width: 4.8rem;
    display: none;
    /* No filter here: on the TV (Tizen 5) a filtered layer above the
       AVPlay video is not drawn at all, so the panel was invisible. */
}

.pl-panel.is-open {
    display: block;
}

.pl-panel__frame {
    padding: 0.02rem;
    background: var(--accent);
    -webkit-clip-path: polygon(0 0, calc(100% - 0.3rem) 0, 100% 0.3rem, 100% 100%, 0.3rem 100%, 0 calc(100% - 0.3rem));
    clip-path: polygon(0 0, calc(100% - 0.3rem) 0, 100% 0.3rem, 100% 100%, 0.3rem 100%, 0 calc(100% - 0.3rem));
}

.pl-panel__in {
    padding: 0.28rem;
    background: rgba(5, 12, 21, 0.96);
    -webkit-clip-path: polygon(0 0, calc(100% - 0.29rem) 0, 100% 0.29rem, 100% 100%, 0.29rem 100%, 0 calc(100% - 0.29rem));
    clip-path: polygon(0 0, calc(100% - 0.29rem) 0, 100% 0.29rem, 100% 100%, 0.29rem 100%, 0 calc(100% - 0.29rem));
}

.pl-panel__head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 0.18rem;
}

.pl-panel__head h2 {
    margin: 0;
    font-size: 0.29rem;
    font-weight: 600;
    letter-spacing: 0.14em;
}

.pl-panel__head span {
    font-family: var(--mono);
    font-size: 0.2rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--text-4);
}

.pl-panel__list {
    max-height: 3.5rem;
    overflow: hidden;
}

.pl-panel__note {
    padding: 0.1rem 0 0.18rem;
    font-family: var(--mono);
    font-size: 0.21rem;
    letter-spacing: 0.06em;
    color: var(--text-3);
}

.pl-opt {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    height: 0.62rem;
    margin-bottom: 0.1rem;
    padding: 0 0.2rem;
    border: 1px solid var(--line);
    background: transparent;
    color: var(--text-2);
    font-size: 0.25rem;
    font-weight: 500;
    letter-spacing: 0.06em;
    text-align: left;
}

.pl-opt span {
    min-width: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.pl-opt svg {
    display: none;
    flex-shrink: 0;
    width: 0.24rem;
    height: 0.24rem;
    margin-left: 0.12rem;
}

.pl-opt.is-on {
    border-color: var(--accent);
    color: var(--accent);
    font-weight: 700;
}

.pl-opt.is-on svg {
    display: block;
}

.pl-opt:focus {
    border-color: var(--text);
    background: var(--text);
    color: var(--ink);
    font-weight: 700;
}

.pl-shift {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.08rem;
    padding-top: 0.18rem;
    border-top: 1px solid var(--line);
}

.pl-shift__label {
    font-family: var(--mono);
    font-size: 0.21rem;
    font-weight: 500;
    letter-spacing: 0.1em;
    color: var(--text-3);
}

.pl-shift__set {
    display: flex;
    align-items: center;
}

.pl-shift__set button {
    width: 0.48rem;
    height: 0.48rem;
    padding: 0;
    border: 1px solid var(--line-hi);
    background: var(--panel-hi);
    color: var(--text);
    font-size: 0.29rem;
    font-weight: 600;
    line-height: 1;
}

.pl-shift__set button:focus {
    border-color: var(--text);
    background: var(--text);
    color: var(--ink);
}

.pl-shift__value {
    width: 1.08rem;
    text-align: center;
    font-family: var(--mono);
    font-size: 0.25rem;
    font-weight: 700;
    color: var(--accent);
}

/* --------------------------------------------
   Playback failed
   -------------------------------------------- */
.pl-error {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(3, 6, 11, 0.94);
    text-align: center;
    cursor: default;
}

.pl.is-error .pl-error {
    display: flex;
}

.pl-error h2 {
    margin: 0.14rem 0 0;
    font-size: 0.44rem;
    font-weight: 600;
    letter-spacing: 0.1em;
}

.pl-error p {
    max-width: 9rem;
    margin: 0.2rem 0 0;
    font-size: 0.27rem;
    line-height: 1.5;
    color: var(--text-2);
}

.pl-error__actions {
    display: flex;
    margin-top: 0.4rem;
}

.pl-error__actions .pl-btn {
    margin: 0 0.08rem;
}

/* --------------------------------------------
   Next episode (end of an episode, with a countdown)
   -------------------------------------------- */
.pl-next {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(3, 6, 11, 0.94);
    text-align: center;
    cursor: default;
}

.pl.is-next .pl-next {
    display: flex;
}

.pl-next h2 {
    max-width: 14rem;
    margin: 0.14rem 0 0;
    font-size: 0.44rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}

.pl-next__note {
    margin: 0.2rem 0 0;
    font-family: var(--mono);
    font-size: 0.24rem;
    font-weight: 500;
    letter-spacing: 0.14em;
    color: var(--accent);
}

/* --------------------------------------------
   "Skip intro": bottom right, also while the controls are hidden.
   No filter here (the TV would not draw the layer over the video).
   -------------------------------------------- */
.pl-skip {
    position: absolute;
    right: 0.96rem;
    bottom: 2.5rem;
    z-index: 5;
    display: flex;
    align-items: center;
    padding: 0.16rem 0.3rem;
    border: 2px solid var(--accent);
    background: rgba(5, 12, 21, 0.88);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
}

.pl-skip.is-on {
    opacity: 1;
}

.pl-skip b {
    margin-right: 0.16rem;
    padding: 0.04rem 0.12rem;
    font-family: var(--mono);
    font-size: 0.22rem;
    font-weight: 700;
    color: var(--ink);
    background: var(--accent);
}

.pl-skip span {
    font-size: 0.26rem;
    font-weight: 700;
    letter-spacing: 0.1em;
}

/* Moving the mark with the arrows: where the film was stays marked, the mark is bigger */
.pl-bar__at {
    display: none;
    position: absolute;
    top: 0.09rem;
    width: 0.06rem;
    height: 0.22rem;
    margin-left: -0.03rem;
    background: rgba(255, 255, 255, 0.55);
}

.pl.is-scrub .pl-bar__at {
    display: block;
}

.pl.is-scrub .pl-bar__thumb {
    top: 0.02rem;
    width: 0.14rem;
    height: 0.36rem;
    margin-left: -0.07rem;
    background: var(--accent);
}

