// What the app remembers on this TV (localStorage): login, favourites,
// history, where each film was left off, and cached film data.
// Same keys and shapes as the web version. ES5 on purpose (Tizen 5.0).
var Store = (function () {
    'use strict';

    function read(key, fallback) {
        try {
            var raw = localStorage.getItem(key);
            return raw ? JSON.parse(raw) : fallback;
        } catch (e) {
            return fallback;
        }
    }

    function write(key, value) {
        try {
            if (value === null) localStorage.removeItem(key);
            else localStorage.setItem(key, JSON.stringify(value));
        } catch (e) { /* storage full or unavailable: carry on without it */ }
    }

    function copy(item, extra) {
        var out = {};
        var key;
        for (key in item) if (item.hasOwnProperty(key)) out[key] = item[key];
        for (key in extra) if (extra.hasOwnProperty(key)) out[key] = extra[key];
        return out;
    }

    var Token = {
        // Plain string, the same key the trial version used
        get: function () { try { return localStorage.getItem('ws_token'); } catch (e) { return null; } },
        set: function (token) { try { localStorage.setItem('ws_token', token); } catch (e) { /* session only */ } },
        clear: function () { write('ws_token', null); write('ws_user', null); },
        user: function () { return read('ws_user', null); },
        setUser: function (user) { write('ws_user', user); }
    };

    var Favorites = {
        all: function () { return read('favorites', []); },
        has: function (title) {
            return Favorites.all().some(function (f) { return f.ident === title || f.title === title; });
        },
        add: function (item) {
            if (Favorites.has(item.title)) return;
            var list = Favorites.all();
            list.unshift(copy(item, {addedAt: Date.now()}));
            write('favorites', list);
        },
        remove: function (title) {
            write('favorites', Favorites.all().filter(function (f) {
                return f.ident !== title && f.title !== title;
            }));
        }
    };

    // "Chci vidět": films and series to watch some day. key = imdb id, else
    // "title year", else the title; series 'tv:<tmdb id>'. A film leaves the
    // list when it is seen to the end (Seen.add).
    var Want = {
        MAX: 200,
        all: function () { var list = read('want_list', []); return list instanceof Array ? list : []; },
        // the same key Seen uses, so a film seen to the end leaves the list
        filmKey: function (item) { return Seen.key(item) || (item && item.title) || ''; },
        // A film saved before TMDB answered has the key "title year"; later
        // the same film comes with its imdb id. An entry matches a key by its
        // key, its imdb id or its "title year", so both ways find it.
        _match: function (w, keys) {
            var own = [w.key, w.imdb_id, Seen.key({q: w.query})];
            for (var i = 0; i < own.length; i++) {
                var o = String(own[i] || '').toLowerCase();
                if (o && keys.indexOf(o) >= 0) return true;
            }
            return false;
        },
        _keys: function (key, query) {
            var keys = [String(key || '').toLowerCase(), String(Seen.key({q: query}) || '')];
            return keys.filter(function (k) { return !!k; });
        },
        has: function (key, query) {
            var keys = Want._keys(key, query);
            return keys.length > 0 && Want.all().some(function (w) { return Want._match(w, keys); });
        },
        add: function (item) {
            if (!item || !item.key || Want.has(item.key, item.query)) return;
            var list = Want.all();
            list.unshift(copy(item, {addedAt: Date.now()}));
            write('want_list', list.slice(0, Want.MAX));
        },
        remove: function (key, query) {
            var keys = Want._keys(key, query);
            var list = Want.all();
            var left = list.filter(function (w) { return !Want._match(w, keys); });
            if (left.length !== list.length) write('want_list', left);
        }
    };

    var History = {
        MAX: 50,
        all: function () { return read('watch_history', []); },
        add: function (item) {
            var list = History.all().filter(function (h) { return h.ident !== item.ident; });
            list.unshift(copy(item, {watchedAt: Date.now()}));
            write('watch_history', list.slice(0, History.MAX));
        },
        clear: function () { write('watch_history', null); }
    };

    var Resume = {
        MIN_POSITION: 30,   // seconds: earlier than this is not worth resuming
        MIN_REMAINING: 60,  // seconds: this close to the end counts as finished
        all: function () { return read('resume_positions', {}); },
        get: function (ident) { return Resume.all()[ident] || null; },
        save: function (ident, position, duration, extra) {
            if (!duration || position < Resume.MIN_POSITION) return;
            if (duration - position < Resume.MIN_REMAINING) { Resume.remove(ident); Seen.add(extra); return; }
            var all = Resume.all();
            all[ident] = copy(extra || {}, {
                position: Math.floor(position), duration: Math.floor(duration), savedAt: Date.now()
            });
            write('resume_positions', all);
        },
        remove: function (ident) {
            var all = Resume.all();
            delete all[ident];
            write('resume_positions', all);
        },
        list: function () {
            var all = Resume.all();
            return Object.keys(all).map(function (ident) {
                return copy(all[ident], {
                    ident: ident,
                    progress: Math.round(all[ident].position / all[ident].duration * 100)
                });
            }).sort(function (a, b) { return b.savedAt - a.savedAt; });
        }
    };

    // Films watched to the end, remembered for longer than the history:
    // 'tt0133093' or 'matrix 1999' (title and year from the search words)
    var Seen = {
        MAX: 3000,
        all: function () { var list = read('seen_titles', []); return list instanceof Array ? list : []; },
        key: function (item) {
            if (!item) return null;
            if (item.imdb_id) return item.imdb_id;
            var q = (item.q || '').toLowerCase().replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
            return /\b(19|20)\d{2}$/.test(q) ? q : null;
        },
        add: function (item) {
            if (item && item.show) { Episodes.mark(item, 2); return; }
            if (!item) return;
            var key = Seen.key(item);
            if (!key) return;
            var list = Seen.all().filter(function (k) { return k !== key; });
            list.unshift(key);
            write('seen_titles', list.slice(0, Seen.MAX));
            Want.remove(key, item.q);
        }
    };

    // Episodes of each series: {<tmdb id>: {seen: {'1x2': 1 started | 2 to the end},
    // last: '1x2', at: time}}. Kept longer than the history (newest 150 series).
    var Episodes = {
        KEEP: 150,
        all: function () { var all = read('seen_episodes', {}); return all && typeof all === 'object' ? all : {}; },
        code: function (title) {
            var m = /S(\d{1,2})E(\d{1,3})/i.exec(title || '');
            return m ? (+m[1]) + 'x' + (+m[2]) : null;
        },
        // item = {show, title: 'Dark S01E02'}; level 1 = playing started, 2 = watched to the end
        mark: function (item, level) {
            var code = item && item.show ? Episodes.code(item.title || item.q) : null;
            if (!code) return;
            var all = Episodes.all();
            var one = all[item.show] || {seen: {}};
            if (!one.seen) one.seen = {};
            one.seen[code] = Math.max(one.seen[code] || 0, level);
            one.last = code;
            one.at = Date.now();
            all[item.show] = one;
            var keys = Object.keys(all).sort(function (a, b) { return (all[b].at || 0) - (all[a].at || 0); });
            keys.slice(Episodes.KEEP).forEach(function (k) { delete all[k]; });
            write('seen_episodes', all);
        }
    };

    // Where the opening titles of a series end (seconds), learnt from the
    // viewer skipping them by hand: {<tmdb id>: {s, at}}
    var Intro = {
        get: function (show) { var hit = show ? read('show_intro', {})[show] : null; return hit ? hit.s : 0; },
        set: function (show, seconds) {
            if (!show) return;
            var all = read('show_intro', {});
            all[show] = {s: Math.round(seconds), at: Date.now()};
            var keys = Object.keys(all).sort(function (a, b) { return all[b].at - all[a].at; });
            keys.slice(150).forEach(function (k) { delete all[k]; });
            write('show_intro', all);
        }
    };

    // Player choices carried over to the next film:
    // audio = language of the last chosen sound track ('en'),
    // subs = 'off' or the language of the last chosen subtitles ('cs').
