        try {
            if (yes) backend.pause(); else backend.resume();
        } catch (e) { toast('PŘEHRÁVAČ', 'TELEVIZE TO TEĎ NEDOVOLILA'); return; }
        paused = yes;
        if (paused) save();
        paintState();
    }

    function togglePlay() { setPaused(!paused); }

    // Seeks are queued: while the TV is still jumping, only the newest
    // target is remembered and done next
    function seekTo(seconds) {
        var duration = backend ? backend.duration() : 0;
        if (!duration) return;
        wanted = Math.max(0, Math.min(duration - 1, seconds));
        fileLine = null;     // the TV sends the right line again after the jump
        paintTime();
        if (!seeking) runSeek();
    }

    function runSeek() {
        var target = wanted;
        var mine = session;
        var finished = false;
        seeking = true;
        function done() {
            if (finished || mine !== session) return;
            finished = true;
            seeking = false;
            if (wanted !== null && Math.abs(wanted - target) > 0.5) runSeek();
            else {
                wanted = null;
                shownSub = null;
                if (resumeAfter) {
                    resumeAfter = false;
                    if (!paused) { try { backend.resume(); } catch (e) { /* plays already */ } }
                }
            }
        }
        backend.seek(target, done);
        setTimeout(done, 8000);   // never stay stuck if the TV does not answer
    }

    function stepText(delta) {
        var size = Math.round(Math.abs(delta));
        var h = Math.floor(size / 3600), m = Math.floor(size % 3600 / 60), sec = size % 60;
        var parts = [];
        if (h) parts.push(h + ' H');
        if (m) parts.push(m + ' MIN');
        if (sec || !parts.length) parts.push(sec + ' S');
        return (delta < 0 ? '−' : '+') + parts.join(' ');
    }

    // Arrows move the mark; the jump comes when they rest (see SCRUB_SETTLE)
    function seek(delta, note) {
        if (!backend || !backend.duration()) return;
        learnIntro();
        if (!scrub) {
            var from = position();
            scrub = {from: from, target: from, timer: null, stopped: false};
            if (!paused) {
                try { backend.pause(); scrub.stopped = true; } catch (e) { /* keeps playing */ }
            }
            $('bar-at').style.left = (from / backend.duration() * 100) + '%';
            on(root, 'is-scrub', true);
        }
        scrub.target = Math.max(0, Math.min(backend.duration() - 1, scrub.target + delta));
        paintTime();
        toast(formatTime(scrub.target), stepText(scrub.target - scrub.from) + ' · ' + (note || 'OK = SKOČIT'));
        clearTimeout(scrub.timer);
        scrub.timer = setTimeout(commitScrub, SCRUB_SETTLE);
    }

    function endScrub() {
        stopHold();
        var s = scrub;
        clearTimeout(s.timer);
        scrub = null;
        on(root, 'is-scrub', false);
        return s;
    }

    function commitScrub() {
        if (!scrub) return;
        var s = endScrub();
        if (Math.abs(s.target - s.from) < 1) {
            if (s.stopped && !paused) { try { backend.resume(); } catch (e) { /* ignore */ } }
            paintTime();
            return;
        }
        if (s.stopped) resumeAfter = true;
        seekTo(s.target);
        toast(formatTime(s.target), stepText(s.target - s.from));
    }

    function cancelScrub() {
        if (!scrub) return;
        var s = endScrub();
        if (s.stopped && !paused) { try { backend.resume(); } catch (e) { /* ignore */ } }
        paintTime();
        toast(formatTime(s.from), 'PŘETÁČENÍ ZRUŠENO');
    }

    // Arrow seeking. A press moves the mark 10 s (30 s when pressed quickly
    // again and again) for fine moves. Holding the arrow moves it on its own,
    // faster and faster, until the arrow is let go.
    var HOLD_AFTER = 300;       // ms held = holding, not a press
    var HOLD_TICK = 50;
    var HOLD_SPEED = 30;        // film seconds per second at the start...
    var HOLD_DOUBLE = 0.6;      // ...twice as fast every 0.6 s held...
    var HOLD_TOP = 900;        // ...up to 15 minutes of film per second
    var HOLD_MAX = 30000;       // stop anyway if the TV never says the key is up
    var runDir = 0;
    var runCount = 0;
    var runAt = 0;
    var hold = null;            // {code, dir, at, timer, tick}

    function arrowSeek(dir, code) {
        code = code || (dir < 0 ? KEY.LEFT : KEY.RIGHT);
        // The TV may repeat the key while it is held: the hold already moves the mark
        if (hold && hold.code === code) return;
        stopHold();
        var now = Date.now();
        if (dir === runDir && now - runAt < 700) runCount += 1; else runCount = 0;
        runDir = dir;
        runAt = now;
        seek(dir * (runCount < 5 ? 10 : 30));
        hold = {code: code, dir: dir, at: now, tick: null,
                timer: setTimeout(startHold, HOLD_AFTER)};
    }

    function startHold() {
        if (!hold || !scrub) { hold = null; return; }
        var h = hold;
        var last = Date.now();
        h.tick = setInterval(function () {
            var now = Date.now();
            var held = (now - h.at - HOLD_AFTER) / 1000;
            var speed = Math.min(HOLD_TOP, HOLD_SPEED * Math.pow(2, held / HOLD_DOUBLE));
            var step = speed * (now - last) / 1000;
            last = now;
            var before = scrub ? scrub.target : 0;
            if (!scrub || now - h.at > HOLD_MAX) { stopHold(); return; }
            seek(h.dir * step, 'PUSŤ = SKOČIT · RYCHLOST ' + Math.round(speed) + '×');
            // At the very start or end: nowhere to go
            if (scrub && scrub.target === before) stopHold();
        }, HOLD_TICK);
    }

    function stopHold() {
        if (!hold) return;
        clearTimeout(hold.timer);
        clearInterval(hold.tick);
        hold = null;
    }

    // Key let go: a hold ends, the jump follows when the arrows rest
    function keyUp(code) {
        if (hold && hold.code === code) stopHold();
    }

    // ------------------------------------------------ opening titles
    function learnIntro() {
        if (!file || !file.show) return;
        if (!introLearn) introLearn = {from: position(), timer: null};
        clearTimeout(introLearn.timer);
        var mine = session;
        introLearn.timer = setTimeout(function () {
            if (mine !== session || !introLearn) return;
            var from = introLearn.from;
            var to = position();
            introLearn = null;
            if (from > INTRO_START_BEFORE || to > INTRO_MAX || to - from < 20) return;
            var known = Store.Intro.get(file.show);
            Store.Intro.set(file.show, to);
            if (Math.abs(known - to) > 5) toast('ÚVOD DO ' + formatTime(to), 'V DALŠÍCH DÍLECH PŮJDE PŘESKOČIT');
        }, INTRO_SETTLE);
    }

    function introEnd() {
        if (!file || !file.show || !backend || failed || nextOpen || panelOpen) return 0;
        var end = Store.Intro.get(file.show);
        var now = position();
        return end && now < end - 3 && now < INTRO_MAX ? end : 0;
    }

    function paintSkip() {
        on($('pl-skip'), 'is-on', !!introEnd());
    }

    function skipIntro() {
        var end = introEnd();
        if (!end) return false;
        seekTo(end);
        toast(formatTime(end), 'ÚVOD PŘESKOČEN');
        paintSkip();
        return true;
    }

    // ------------------------------------------------ saved position
    function save() {
        if (!backend || !file || failed || seeking) return;
        Store.Resume.save(file.ident, backend.now(), backend.duration(), {
            title: file.title || file.name, name: file.name, info: file.info || '',
            imdb_id: file.imdb_id || '', q: file.q || '', show: file.show || ''
        });
        lastSaved = Date.now();
    }

    // ------------------------------------------------ subtitles
    function subLines() {
        if (!backend) return [];
        if (subSource === 'web' && cues) return Subs.at(cues, backend.now() - subOffset);
        if (subSource === 'file' && fileLine && backend.now() < fileLine.end) return [fileLine.text];
        return [];
    }

    // A line from the video's own subtitle track (sent by the TV)
    function fileText(text, ms, stopMs) {
        if (subSource !== 'file' || !backend) return;
        var line = Subs.clean(text);
        if (!line) fileLine = null;
        else {
            var now = backend.now();
            var end = stopMs ? stopMs / 1000 : now + (ms ? ms / 1000 : 4);
            fileLine = {text: line, end: end > now ? end : now + (ms ? ms / 1000 : 4)};
        }
        paintSubs();
    }

    function paintSubs() {
        var lines = subLines();
        var key = lines.join('\n\n');
        if (key === shownSub) return;
        shownSub = key;
        subBox.textContent = '';
        lines.forEach(function (text) {
            var p = document.createElement('p');
            p.textContent = text;
            subBox.appendChild(p);
        });
    }

    function panelOptions() {
        var list = panelOpen === 'audio' ? audioList : subList;
        var options = Array.prototype.slice.call(list.querySelectorAll('.pl-opt'));
        return panelOpen === 'audio' ? options : options.concat([subOff]);
    }

    function markOption(button) {
        Array.prototype.slice.call(subList.querySelectorAll('.pl-opt')).concat([subOff])
            .forEach(function (b) { on(b, 'is-on', b === button); });
        showShift();
    }

    // Only one kind of subtitles at a time: the video's own track goes
    // quiet whenever something else is chosen
    function quietFile() {
        if (subSource === 'file' && backend) { try { backend.setText(-1); } catch (e) { /* already quiet */ } }
        fileLine = null;
    }

    function subsOff() {
        subTouched = true;
        quietFile();
        subSource = '';
        cues = null;
        subLang = '';
        markOption(subOff);
        paintSubs();
        paintInfo();
    }

    // i = index into backend.texts()
    function useFileText(i, track, button) {
        try {
            backend.setText(i);
        } catch (e) {
            toast('TITULKY', 'TELEVIZE STOPU NEPŘEPNULA');
            return false;
        }
        subSource = 'file';
        fileIndex = i;
        cues = null;
        fileLine = null;
        subLang = (track.lang || '').toUpperCase();
        shownSub = null;
        markOption(button);
        paintSubs();
        paintInfo();
        return true;
    }

    function useSubtitle(sub, button) {
        var mine = session;
        subTouched = true;
        toast(langName(sub.language) || 'TITULKY', 'NAČÍTÁM…');
        Subs.load(sub, function (err, loaded) {
            if (mine !== session) return;
            if (err) { toast('TITULKY', 'NEPODAŘILO SE NAČÍST'); return; }
            quietFile();
            subSource = 'web';
            webUrl = sub.url;
            if (Subs.langKey(sub.language)) Store.Prefs.set('subs', Subs.langKey(sub.language), file && file.show);
            cues = loaded;
            subLang = (sub.language || '').toUpperCase();
            shownSub = null;
            markOption(button);
            paintInfo();
            toast(langName(sub.language) || 'TITULKY', 'TITULKY ZAPNUTY');
            closePanel();
        });
    }

    function shiftText() {
        return (subOffset < 0 ? '−' : '+') + Math.abs(subOffset).toFixed(1).replace('.', ',') + ' s';
    }

    // The shift works on downloaded subtitles only (the TV times its own)
    function showShift() {
        $('shift-value').textContent = shiftText();
        $('sub-shift').style.display = subSource === 'web' ? '' : 'none';
    }

    function changeShift(delta) {
        subOffset = Math.round((subOffset + delta) * 10) / 10;
        if (file) Store.SubShift.set(file.ident, subOffset);
        showShift();
        shownSub = null;
        paintSubs();
        paintInfo();
    }

    function subNote(text) {
        subWeb.textContent = '';
        var p = document.createElement('div');
        p.className = 'pl-panel__note';
        p.textContent = text;
        subWeb.appendChild(p);
    }

    // Subtitle tracks inside the video, at the top of the list
    function fillFileTexts() {
        subFile.textContent = '';
        if (!backend) return;
        backend.texts().forEach(function (track, i) {
            var isOn = subSource === 'file' && fileIndex === i;
            subFile.appendChild(option(track.label, isOn, function (button) {
                if (useFileText(i, track, button)) {
                    subTouched = true;
                    if (Subs.langKey(track.lang)) Store.Prefs.set('subs', Subs.langKey(track.lang), file && file.show);
                    toast(langName(track.lang) || 'TITULKY', 'TITULKY Z VIDEA ZAPNUTY');
                    closePanel();
                }
            }));
        });
    }

    function option(text, isOn, click) {
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'pl-opt' + (isOn ? ' is-on' : '');
        var label = document.createElement('span');
        label.textContent = text;
        button.appendChild(label);
        button.insertAdjacentHTML('beforeend', CHECK);
        button.addEventListener('click', function () { click(button); });
        return button;
    }

    function loadSubtitles() {
        var mine = session;
        subNote('Hledám titulky…');
        var episode = /S(\d{1,2})E(\d{1,3})\s*$/i.exec(file.title || '');
        Subs.search({
            imdb_id: file.imdb_id, title: file.title || file.name,
            season: episode ? +episode[1] : 0, episode: episode ? +episode[2] : 0
        }, function (err, list) {
            if (mine !== session) return;
            if (err) { subNote(err.message); return; }
            if (!list.length) { subNote('Na OpenSubtitles se žádné titulky nenašly.'); return; }
            subWeb.textContent = '';
            list.forEach(function (sub) {
                var name = langName(sub.language) || 'TITULKY';
                subWeb.appendChild(option(name + (sub.release ? ' · ' + sub.release : ''),
                    subSource === 'web' && sub.url === webUrl,
                    function (button) { useSubtitle(sub, button); }));
            });
            subsLoaded = true;
            // Nothing to pick in the video itself: start on the first download
            if (panelOpen === 'subs' && !subFile.firstChild && document.activeElement === subOff) {
                panelOptions()[0].focus();
            }
        });
    }

    // Foreign sound and no Czech/Slovak subtitles in the file: switch on the
    // first Czech (else Slovak) subtitles from OpenSubtitles by themselves.
    // Not remembered as the viewer's choice; the subtitle panel changes them.
    function autoSubtitles() {
        var heard = '';
        backend.audio().forEach(function (t) { if (t.on) heard = Subs.langKey(t.lang); });
        var texts = backend.texts().map(function (t) { return Subs.langKey(t.lang); });
        var dub = false;
        try { dub = /^(CZ|SK)$/.test(StreamInfo.describe(file.name || file.title || '', 0).language); } catch (e) { /* unknown */ }
        if (subSource || !Subs.autoWanted(Store.Prefs.get(file && file.show), heard, texts, dub)) return;
        var mine = session;
        var episode = /S(\d{1,2})E(\d{1,3})\s*$/i.exec(file.title || '');
        Subs.search({
            imdb_id: file.imdb_id, title: file.title || file.name,
            season: episode ? +episode[1] : 0, episode: episode ? +episode[2] : 0
        }, function (err, list) {
            if (mine !== session || subTouched || subSource || err || !list) return;
            var pick = null;
            ['cs', 'sk'].forEach(function (lang) {
                if (pick) return;
                pick = list.filter(function (s) { return Subs.langKey(s.language) === lang; })[0] || null;
            });
            if (!pick) return;
            Subs.load(pick, function (err2, loaded) {
                if (mine !== session || subTouched || subSource || err2 || !loaded || !loaded.length) return;
                subSource = 'web';
                webUrl = pick.url;
                cues = loaded;
                subLang = (pick.language || '').toUpperCase();
                shownSub = null;
                markOption(null);   // VYPNUTO is no longer the one in use
                paintSubs();
                paintInfo();
                toastAfter('TITULKY ' + (langName(pick.language) || ''), 'OPENSUBTITLES · ZMĚNA V PANELU TITULKŮ');
            });
        });
    }

    // ------------------------------------------------ audio tracks
    function fillAudio() {
        audioList.textContent = '';
        backend.audio().forEach(function (track, i) {
            audioList.appendChild(option(track.label, track.on, function () {
                var at = backend.now();
                try {
                    backend.setAudio(i);
                } catch (e) {
                    toast('ZVUK', 'TELEVIZE STOPU NEPŘEPNULA');
                    closePanel();
                    return;
                }
                // Some TVs restart the film on a track change: keep the place
                setTimeout(function () {
                    if (backend && Math.abs(backend.now() - at) > 5) seekTo(at);
                }, 700);
                if (Subs.langKey(track.lang)) Store.Prefs.set('audio', Subs.langKey(track.lang), file && file.show);
                paintAudioButton();
                toast(track.label, 'ZVUK PŘEPNUT');
                closePanel();
            }));
        });
    }

    // ------------------------------------------------ last choices
    // The sound language and subtitles chosen last time are used again
    // when this file has such a track. Subtitles in the same language as
    // the sound are not switched on (a Czech dub needs no Czech subtitles).
    // Returns a short note of what was switched, or ''.
    function applyPrefs() {
        var prefs = Store.Prefs.get(file && file.show);
        var note = [];
        var audio = backend.audio();
        var i;
        if (prefs.audio && audio.length > 1) {
            for (i = 0; i < audio.length; i++) {
                if (Subs.langKey(audio[i].lang) !== prefs.audio) continue;
                if (!audio[i].on) {
                    try { backend.setAudio(i); note.push('ZVUK ' + langName(prefs.audio)); } catch (e) { /* keep the TV's choice */ }
                }
                break;
            }
        }
        var heard = '';
        backend.audio().forEach(function (t) { if (t.on) heard = Subs.langKey(t.lang); });
        if (prefs.subs && prefs.subs !== 'off' && prefs.subs !== heard) {
            var texts = backend.texts();
            for (i = 0; i < texts.length; i++) {
                if (Subs.langKey(texts[i].lang) === prefs.subs) {
                    if (useFileText(i, texts[i], null)) note.push('TITULKY ' + langName(prefs.subs));
                    break;
                }
            }
        }
        paintAudioButton();
        return note.join(' · ');
    }

    // ------------------------------------------------ side panels
    function keepInView(button) {
        var list = subList.contains(button) ? subList : (audioList.contains(button) ? audioList : null);
        if (!list) return;
        var top = button.offsetTop - list.offsetTop;
        if (top < list.scrollTop) list.scrollTop = top;
        else if (top + button.offsetHeight > list.scrollTop + list.clientHeight) {
            list.scrollTop = top + button.offsetHeight - list.clientHeight;
        }
    }

    function openPanel(which) {
        if (panelOpen) closePanel();
        panelOpen = which;
        on(root, 'is-panel', true);
        on(root, 'is-ui', true);
        on($(which === 'audio' ? 'audio-panel' : 'sub-panel'), 'is-open', true);
        clearTimeout(uiTimer);
        if (which === 'audio') fillAudio(); else fillFileTexts();
        var options = panelOptions();
        var current = options.filter(function (b) { return has(b, 'is-on'); })[0] || options[0];
        if (current) { current.focus(); keepInView(current); }
        if (which === 'subs' && !subsLoaded) loadSubtitles();
    }

    function closePanel() {
        if (!panelOpen) return;
        var opener = panelOpen === 'audio' ? btnAudio : btnSubs;
        panelOpen = '';
        on(root, 'is-panel', false);
        on($('sub-panel'), 'is-open', false);
        on($('audio-panel'), 'is-open', false);
        showUi(opener);
    }

    function panelKey(code, active) {
        var options = panelOptions();
        var minus = $('shift-minus');
        var plus = $('shift-plus');
        var at = options.indexOf(active);
        var next = null;
        if (panelOpen === 'audio') {
            if (code === KEY.UP) next = options[Math.max(0, at - 1)];
            else if (code === KEY.DOWN) next = options[Math.min(options.length - 1, at + 1)];
        } else if (active === minus || active === plus) {
            if (code === KEY.UP) next = options[options.length - 1];
            else if (code === KEY.LEFT) next = minus;
            else if (code === KEY.RIGHT) next = plus;
        } else if (code === KEY.UP) {
            next = options[Math.max(0, at - 1)];
        } else if (code === KEY.DOWN) {
            next = at < 0 ? options[0] : (at + 1 < options.length ? options[at + 1] :
                (subSource === 'web' ? minus : null));
        }
        if (next) { next.focus(); keepInView(next); }
    }

    // ------------------------------------------------ next episode
    // Shortly before the end of an episode (opened from a series, so the
    // series is known) the next one is looked up in TMDB and on Webshare.
    // At the end it is offered with a countdown; Back cancels. Films: nothing.

    function searchBoth(q, alt, done) {
        var token = Store.Token.get();
        Webshare.search(q, token, 40, function (err, found) {
            found = err ? [] : found;
            if (!alt) { done(found); return; }
            Webshare.search(alt, token, 40, function (err2, more) {
                var seen = {};
                found.forEach(function (f) { seen[f.ident] = true; });
                (err2 ? [] : more).forEach(function (f) { if (!seen[f.ident]) found.push(f); });
                done(found);
            });
        });
    }

    function lookForNext() {
        var playing = file;
        var code = StreamInfo.episodeCode(playing.title);
        if (!playing.show || !code) { nextState = 'none'; return; }
        nextState = 'looking';
        var mine = session;
        function none() {
            if (mine !== session) return;
            nextState = 'none';
            if (nextOpen) stop();
        }
        Tmdb.show(+playing.show, function (err, show) {
            if (mine !== session) return;
            if (err || !show) { none(); return; }
            var n = StreamInfo.nextEpisode(show.seasons, code.season, code.episode);
            if (!n) { none(); return; }
            findEpisode(show, n.season, n.episode, playing.name, playing.imdb_id, function (found) {
                if (mine !== session) return;
                next = found;
                nextState = 'found';
                if (nextOpen) offerNext();
            });
        });
    }

    // One episode of a series on Webshare: done({code, name, what, files}).
    // what = the file to play (like the file "like": same quality and
    // language), or null; files = params of #/files to choose by hand.
    function findEpisode(show, season, episode, like, imdb, done) {
        var codeText = StreamInfo.codeText(season, episode);
        var q = show.title + ' ' + codeText;
        var alt = show.original_title && show.original_title.toLowerCase() !== show.title.toLowerCase() ?
            show.original_title + ' ' + codeText : '';
        imdb = imdb || show.imdb_id || '';
        var id = String(show.tmdb_id);
        Tmdb.season(show.tmdb_id, season, function (err, episodes) {
            var name = '';
            (err ? [] : episodes).forEach(function (e) { if (e.number === episode) name = e.name; });
            searchBoth(q, alt, function (files) {
                var i = StreamInfo.pickEpisode(files, season, episode, like || '');
                var what = null;
                if (i >= 0) {
                    var info = StreamInfo.describe(files[i].name, files[i].size);
                    what = {ident: files[i].ident, name: files[i].name, title: q, q: q,
                            info: info.res + ' · ' + info.label, imdb_id: imdb, show: id};
                }
                done({code: codeText, name: name, what: what,
                      files: {q: q, alt: alt, title: q, imdb_id: imdb, ep: 1, show: id}});
            });
        });
    }

    function nextButtons() {
        return [$('next-play'), $('next-cancel')].filter(function (b) { return b.style.display !== 'none'; });
    }

    // The episode has ended
    function openNext() {
        nextOpen = true;
        if (panelOpen) closePanel();
        clearTimeout(uiTimer);
        on(root, 'is-ui', false);
        on(root, 'is-next', true);
        wait(false);
        subBox.textContent = '';
        if (nextState === 'found') { offerNext(); return; }
        if (!nextState) lookForNext();
        $('next-title').textContent = 'HLEDÁM DALŠÍ DÍL…';
        $('next-note').textContent = 'ZPĚT = ZAVŘÍT';
        $('next-play').style.display = 'none';
        $('next-cancel').focus();
        var mine = session;
        // Never wait for an answer for long
        nextTimer = setTimeout(function () { if (mine === session && nextState !== 'found') stop(); }, 15000);
    }

    function offerNext() {
        clearTimeout(nextTimer);
        clearInterval(nextTimer);
        $('next-title').textContent = next.code + (next.name ? ' · ' + next.name : '');
        $('next-play').textContent = next.what ? 'PŘEHRÁT TEĎ' : 'VYBRAT SOUBOR';
        $('next-play').style.display = '';
        $('next-play').focus();
        nextLeft = NEXT_COUNTDOWN;
        function paint() {
            $('next-note').textContent = (next.what ? 'ZAČNE ZA ' : 'SEZNAM SOUBORŮ ZA ') + nextLeft + ' S · ZPĚT = ZRUŠIT';
        }
        paint();
        nextTimer = setInterval(function () {
            nextLeft -= 1;
            if (nextLeft <= 0) playNext(); else paint();
        }, 1000);
    }

    function playNext() {
        var n = next;
        stop();
        if (!n) return;
        var list = App.url('files', n.files);
        if (!n.what) { App.go(list); return; }
        play(n.what, function () { App.go(list); });
    }

    function nextKey(code, active) {
        if (BACK_KEYS.indexOf(code) >= 0 || code === KEY.STOP) { stop(); return; }
        if (code === KEY.ENTER && active && active.click) { active.click(); return; }
        var buttons = nextButtons();
        var at = buttons.indexOf(active);
        if (code === KEY.LEFT) buttons[Math.max(0, at - 1)].focus();
        else if (code === KEY.RIGHT) buttons[Math.min(buttons.length - 1, at + 1)].focus();
        else if (at < 0) buttons[0].focus();
    }

    // ------------------------------------------------ start and stop
    function setup() {
        if (ready) return;
        ready = true;
        root = $('pl');
        bar = $('bar');
        btnClose = $('btn-close');
        btnPlay = $('btn-play');
        btnSubs = $('btn-subs');
