        btnPlay.addEventListener('click', togglePlay);
        $('btn-back').addEventListener('click', function () { seek(-10); });
        $('btn-fwd').addEventListener('click', function () { seek(30); });
        $('btn-other').addEventListener('click', otherStream);
        $('err-other').addEventListener('click', otherStream);
        $('err-back').addEventListener('click', stop);
        $('next-play').addEventListener('click', playNext);
        $('next-cancel').addEventListener('click', stop);
        subOff.addEventListener('click', function () { subsOff(); Store.Prefs.set('subs', 'off', file && file.show); closePanel(); });
        $('shift-minus').addEventListener('click', function () { changeShift(-0.5); });
        $('shift-plus').addEventListener('click', function () { changeShift(0.5); });
