            if (!tracks.length) toast('ZVUK', 'TELEVIZE STOPY NEUKÁZALA');
            else if (tracks.length < 2) toast('ZVUK', 'SOUBOR MÁ JEN JEDNU STOPU');
            else openPanel('audio');
        });
        // Pointer (mouse, or a remote with a cursor): click the bar to jump there
        bar.addEventListener('click', function (e) {
            var box = bar.getBoundingClientRect();
            if (!backend || !backend.duration() || !box.width) return;
            seekTo(Math.max(0, Math.min(1, (e.clientX - box.left) / box.width)) * backend.duration());
            toast(formatTime(wanted !== null ? wanted : position()), 'SKOK');
        });
        document.addEventListener('visibilitychange', function () {
            if (!backend) return;
            if (document.hidden) { save(); backend.sleep(); } else backend.wake();
        });
