    function screenSaver(allow) {
        try {
            var states = webapis.appcommon.AppCommonScreenSaverState;
            webapis.appcommon.setScreenSaver(allow ? states.SCREEN_SAVER_ON : states.SCREEN_SAVER_OFF);
        } catch (e) { /* not on a TV */ }
