    function show(yes) {
        if (yes) scrollY = window.pageYOffset;
        document.body.className = yes ? 'is-playing' : '';
        document.documentElement.className = yes ? 'is-playing' : '';
        $('player').style.display = yes ? '' : 'none';
        if (!yes) window.scrollTo(0, scrollY);
    }

    function playbackFailed(reason) {
        if (failed || !file) return;
        failed = true;
        try {
            Report.send('playback', 'PŘEHRÁVÁNÍ SELHALO · ' + (file.info || '?') +
                (reason && typeof reason !== 'object' ? ' · ' + reason : ''),
                typeof webapis !== 'undefined' && webapis.avplay ? 'AVPLAY' : 'HTML5');
        } catch (e) { /* no reports */ }
        if (panelOpen) closePanel();
        on(root, 'is-error', true);
        wait(false);
        $('err-other').focus();
    }

    // what: {ident, name, title, info, imdb_id, q}; fail(message) when
    // Webshare gives no link (the player is not opened then)
    function play(what, fail) {
        setup();
        var asked = ++session;
        returnFocus = document.activeElement;
        Webshare.fileLink(what.ident, Store.Token.get(), function (err, link) {
            if (asked !== session) return;
            if (err) { if (fail) fail(err.message); return; }
            file = what;
            paused = false;
            failed = false;
            panelOpen = '';
            wanted = null;
            seeking = false;
            subSource = '';
            cues = null;
            fileLine = null;
            fileIndex = -1;
            subLang = '';
            subOffset = Store.SubShift.get(what.ident);
            subsLoaded = false;
            subTouched = false;
            webUrl = '';
            shownSub = null;
            lastSaved = Date.now();
            next = null;
            nextState = '';
            nextOpen = false;

            root.className = 'pl is-ui';
            on($('sub-panel'), 'is-open', false);
            on($('audio-panel'), 'is-open', false);
            $('pl-title').textContent = file.title || file.name || '';
            $('t-now').textContent = '0:00';
            $('t-left').textContent = '−0:00';
            $('bar-fill').style.width = '0%';
            $('bar-thumb').style.left = '0%';
            subFile.textContent = '';
            subWeb.textContent = '';
            markOption(subOff);
            showShift();
            paintInfo();
            paintSubs();
            btnAudio.textContent = 'ZVUK';
            show(true);
            wait(true);
            screenSaver(false);
            Store.History.add({ident: file.ident, title: file.title || file.name, name: file.name,
                               imdb_id: file.imdb_id || '', q: file.q || '', info: file.info || '',
                               show: file.show || ''});
            Store.Episodes.mark(file, 1);
            introLearn = null;

            var make = (typeof webapis !== 'undefined' && webapis.avplay) ? avBackend : htmlBackend;
            backend = make(link, function () {
                if (asked !== session) return;
                wait(false);
                var applied = applyPrefs();
                try { autoSubtitles(); } catch (e) { /* subtitles stay as they are */ }
                var saved = Store.Resume.get(file.ident);
                if (saved && saved.position >= Store.Resume.MIN_POSITION &&
                        saved.position < backend.duration() - Store.Resume.MIN_REMAINING) {
                    seekTo(saved.position);
                    toast(formatTime(saved.position), 'POKRAČUJI, KDE JSTE SKONČILI');
                } else if (applied) {
                    toast('JAKO MINULE', applied);
                }
                paintState();
            }, function (reason) {
                if (asked === session) playbackFailed(reason);
            }, function () {
                if (asked !== session) return;
                Store.Resume.remove(file.ident);
                Store.Seen.add(file);
                failed = true;      // nothing more to save
                if (file.show && StreamInfo.episodeCode(file.title) && nextState !== 'none') openNext();
                else stop();
            }, function (text, ms, stopMs) {
                if (asked === session) fileText(text, ms, stopMs);
            });
            paintState();
            showUi(bar);
            clearInterval(ticker);
            ticker = setInterval(function () {
                if (!backend || failed) return;
                if (!nextState && file.show && backend.duration() &&
                        backend.duration() - backend.now() < NEXT_LOOK_BEFORE) lookForNext();
                if (uiVisible()) paintTime();
                paintSubs();
                paintSkip();
                if (!paused && Date.now() - lastSaved > SAVE_EVERY) save();
            }, 200);
        });
    }

    function stop() {
        if (!file) return;
        save();
        session += 1;
        clearInterval(ticker);
        clearTimeout(uiTimer);
        clearTimeout(toastTimer);
        clearTimeout(nextTimer);
        clearInterval(nextTimer);
        nextOpen = false;
        if (root) on(root, 'is-next', false);
        if (introLearn) { clearTimeout(introLearn.timer); introLearn = null; }
        stopHold();
        if (scrub) endScrub();
        resumeAfter = false;
        if (root) on($('pl-skip'), 'is-on', false);
        if (backend) backend.close();
        backend = null;
        file = null;
        failed = false;
        panelOpen = '';
        screenSaver(true);
        show(false);
        // Home shows the "continue watching" row: draw it again with the new position
        if (App.current() === 'home') App.refresh();
        else if (returnFocus && returnFocus.focus) returnFocus.focus();
    }

    function otherStream() {
        var was = file;
        stop();
        if (was && App.current() !== 'files') {
            App.go(App.url('files', {q: was.q || was.title || was.name, title: was.title, imdb_id: was.imdb_id}));
        }
    }

    // ------------------------------------------------ remote control
    function key(code) {
        if (!file) return;
        var active = document.activeElement;
        var arrow = code >= KEY.LEFT && code <= KEY.DOWN;

        if (nextOpen) { nextKey(code, active); return; }
        if (failed) {
            if (BACK_KEYS.indexOf(code) >= 0 || code === KEY.STOP) stop();
            else if (code === KEY.ENTER && active && active.click) active.click();
            else if (code === KEY.LEFT) $('err-other').focus();
            else if (code === KEY.RIGHT) $('err-back').focus();
            return;
        }
        // While the mark moves: Back cancels, OK and play jump now, other keys jump first
        if (scrub) {
            var moving = code === KEY.LEFT || code === KEY.RIGHT || code === KEY.RW || code === KEY.FF;
            if (BACK_KEYS.indexOf(code) >= 0) { cancelScrub(); showUi(); return; }
            if (code === KEY.ENTER || code === KEY.SPACE || code === KEY.PLAY || code === KEY.PLAYPAUSE) {
                commitScrub();
                showUi();
                return;
            }
            if (!moving) commitScrub();
        }
        if (BACK_KEYS.indexOf(code) >= 0) {
            if (panelOpen) closePanel(); else stop();
            return;
        }
        if (code === KEY.STOP) { stop(); return; }
        if (code === KEY.PLAYPAUSE) { togglePlay(); return; }
        if (code === KEY.PLAY) { setPaused(false); return; }
        if (code === KEY.PAUSE) { setPaused(true); return; }
        if (code === KEY.RW || code === KEY.FF) {
            if (panelOpen) closePanel();
            showUi(bar);
            arrowSeek(code === KEY.RW ? -1 : 1, code);
            return;
        }
        if (code !== KEY.ENTER && code !== KEY.SPACE && !arrow) return;

        if (panelOpen) {
            if (code === KEY.ENTER || code === KEY.SPACE) { if (active && active.click) active.click(); }
            else panelKey(code, active);
            return;
        }

        // Opening titles on screen: OK skips them
        if ((code === KEY.ENTER || code === KEY.SPACE) && (!uiVisible() || active === bar) && skipIntro()) return;

        // Controls hidden: left/right seek straight away, anything else wakes them up
        if (!uiVisible()) {
            if (code === KEY.LEFT || code === KEY.RIGHT) {
                showUi(bar);
                arrowSeek(code === KEY.LEFT ? -1 : 1, code);
            } else {
                if (code === KEY.ENTER || code === KEY.SPACE) togglePlay();
                showUi(code === KEY.DOWN ? btnPlay : bar);
            }
            return;
        }

        showUi();
        var at = ROW.indexOf(active);
        if (code === KEY.SPACE) {
            togglePlay();
        } else if (code === KEY.ENTER) {
            if (active === bar || (at < 0 && active !== btnClose)) togglePlay(); else active.click();
        } else if (active === bar) {
            if (code === KEY.LEFT) arrowSeek(-1);
            else if (code === KEY.RIGHT) arrowSeek(1);
            else if (code === KEY.UP) btnClose.focus();
            else btnPlay.focus();
        } else if (active === btnClose) {
            if (code === KEY.DOWN) bar.focus();
        } else if (at >= 0) {
            if (code === KEY.LEFT && at > 0) ROW[at - 1].focus();
            else if (code === KEY.RIGHT && at < ROW.length - 1) ROW[at + 1].focus();
            else if (code === KEY.UP) bar.focus();
        } else {
            btnPlay.focus();
        }
    }

    return {play: play, key: key, keyUp: keyUp, findEpisode: findEpisode, active: function () { return !!file; }};
})();

