            if (over) return;
            over = true;
            found.sort(function (a, b) { return a.ep.date < b.ep.date ? 1 : (a.ep.date > b.ep.date ? -1 : 0); });
            done(found.slice());
        }
        if (!left) { finish(); return; }
        var timer = setTimeout(finish, FRESH_WAIT);
        mine.forEach(function (me) {
            Tmdb.show(+me.show, function (err, show) {
                var ep = !err && show ? Series.fresh(me, show, Date.now()) : null;
                if (ep) found.push({show: show, ep: ep});
                if (--left) return;
                clearTimeout(timer);
                if (over) App.newEpisodes(found.length); else finish();
            });
        });
    }
    // The menu count again (after an episode was seen to the end)
    App.countNewEpisodes = function () {
