    function airedText(iso) {
        var p = iso.split('-');
        var day = new Date(+p[0], +p[1] - 1, +p[2]).getTime();
        var today = new Date();
        today = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime();
        var days = Math.round((today - day) / (24 * 3600 * 1000));
        if (days <= 0) return 'VYŠEL DNES';
        if (days === 1) return 'VYŠEL VČERA';
        return 'VYŠEL PŘED ' + days + ' DNY';
    }

    // list = freshEpisodes(), index = which one; art = Home background box
    function episodeHero(list, index, art) {
