            var e = (episodes || []).filter(function (x) { return x.number === ep.episode; })[0];
            if (err || !e || !e.name) return;
            codeText.textContent = code + ' · ' + e.name.toUpperCase();
        });
        if (show.networks) {
            meta.appendChild(el('i', null, '/'));
            meta.appendChild(el('span', null, show.networks));
        }

        var play = html('a', 'hc-btn', ICON_PLAY);
