    // Landscape picture of the film (or of the series) behind the card's text.
    // Looked up on TMDB, cached for a week; the card stays plain without it.
    function continueArt(item, panel) {
        function put(address) {
            if (!address) return;
            panel.insertBefore(App.lazyImg('hc-cont__art', address.replace('/w1280/', '/w780/')), panel.firstChild);
            panel.insertBefore(el('span', 'hc-cont__shade'), panel.firstChild.nextSibling);
        }
        if (item.show) {
            Tmdb.show(+item.show, function (err, show) { if (!err && show) put(show.backdrop || show.poster); });
            return;
        }
        var y = /\b((?:19|20)\d{2})\s*$/.exec(item.q || '');
        var title = (item.title || (y ? item.q.slice(0, y.index) : item.q) || '').replace(/\s*S\d{1,2}E\d{1,3}.*$/i, '');
        if (!title) return;
        Tmdb.posterFor({title: title, year: y ? y[1] : '', imdb_id: item.imdb_id}, 'movie', function (err, art) {
            if (!err && art) put(art.backdrop || art.poster);
        });
    }

