            if (!page.alive()) return;
            Tips.keepGood(Tips.shuffle(films.slice(0, 40), Tips.today()), TIPS_SHOWN, page.alive, function (film) {
                if (wait.parentNode) row.removeChild(wait);
                row.appendChild(poster(film));
            }, function (shown) {
                if (!shown && section.parentNode) section.parentNode.removeChild(section);
