    // December brings Christmas films, October horror classics: a row from
    // the collection that belongs to this month, if there is one
    function seasonalSection(view, page) {
        var month = parseInt(Store.read('test_month', 0), 10) || (new Date().getMonth() + 1);
        Collections.index(function (err, groups) {
            var picks = err ? [] : Collections.seasonal(groups, month);
            if (!picks.length || !page.alive()) return;
            var pick = picks[Tips.today() % picks.length];
            Collections.getJson(pick.file, function (err2, films) {
                if (err2 || !(films instanceof Array) || !films.length || !page.alive()) return;
                var row = el('div', 'hc-row');
                Tips.shuffle(films, Tips.today()).slice(0, 20).forEach(function (f) {
                    row.appendChild(poster({kind: 'movie', title: f.title, year: f.year, poster: f.poster,
