                var more = el('a', 'hc-section__more', 'CELÁ KOLEKCE', {href: url('list', {id: 'col-' + pick.id})});
                head.appendChild(more);
                var section = add(el('section', 'hc-section'), head, row);
                var after = view.querySelector('.hc-cont') ? view.querySelector('.hc-cont').parentNode.parentNode : null;
                view.insertBefore(section, after ? after.nextSibling : view.children[1] || null);
            });
