    App.screen('files', {
        header: false,
        bare: true,
        render: function (params, view, page) {
            var q = params.q || '';
            var year = /\b((?:19|20)\d{2})\s*$/.exec(q);
            var title = params.title || (year ? q.slice(0, year.index).trim() : q) || q;

            var bg = el('div', 'hc-detail-bg');
            page.backdrop.appendChild(bg);

            var filmBox = el('section', 'hc-detail__film');
            var count = el('span', 'hc-pick-head__count');
            var filters = el('div', 'hc-filters');
            var list = el('div', 'hc-streams');
            var status = el('p', 'hc-pick-empty', 'Hledám soubory na Webshare…');
            var note = el('p', 'hc-pick-note', '[i] PŘEHRAJE TV = odhad podle názvu souboru: formát, který televize zvládne přehrát.');
            note.style.display = 'none';
            var streams = add(el('section', 'hc-detail__streams'),
                add(el('div', 'hc-pick-head'),
                    add(el('div'), el('span', 'hc-kicker', '// DOSTUPNÉ PŘENOSY · WEBSHARE'), el('h2', null, 'VYBER VERZI')),
                    count),
                filters, list, status, note);
            add(view, add(el('div', 'hc-detail'), filmBox, streams));

            // What the files must match: the names of the film (or of the
            // series plus the episode code), see StreamInfo.relevance
            var code = params.ep ? StreamInfo.episodeCode(q) : null;
            function noCode(text) { return (text || '').replace(/\s*S\d{1,2}E\d{1,3}\s*/i, ' ').trim(); }
            var names = code ? [noCode(q), noCode(params.alt)] : [title, year ? q.slice(0, year.index) : q];
            var fitOpts = code ? {season: code.season, episode: code.episode} : {year: year ? +year[1] : null};

            // Files are searched under every name: the one asked for, the
            // original name of the series (alt), and the film's original
            // title once TMDB tells it ("Klony útočí" -> "Attack of the Clones")
            var found = [];
            var seen = {};
            var searchError = null;
            var waiting = 1;    // the TMDB answer (films) + each search
            // The list goes up as soon as a search finds fitting files and
            // is drawn again, complete, when every search has answered
            function finish() { shown(searchError, found, --waiting === 0); }
            var asked = [];
            function search(text) {
                var key = StreamInfo.normalize(text);
                if (!key || asked.indexOf(key) >= 0) return;
                asked.push(key);
                waiting += 1;
                Webshare.search(text, Store.Token.get(), 40, function (err, files) {
                    if (err) searchError = err;
                    else files.forEach(function (f) { if (!seen[f.ident]) { seen[f.ident] = true; found.push(f); } });
                    finish();
                });
            }
            search(q);
            if (params.alt) search(params.alt);
            // Webshare finds little for "Star Wars: Epizoda II – Klony útočí";
            // plain words, also without "Epizoda II", find much more
            if (!code) StreamInfo.searchVariants(title, fitOpts.year).forEach(search);

            // Left side: plain title at once, film facts when TMDB answers.
            // An episode (opened from a series) is not looked up as a film.
            var filmImdb = null;
            filmSide(filmBox, null, title, q, params.imdb_id, !!params.ep);
            if (params.ep) finish();
            else Tmdb.movieDetail(params.imdb_id, title, year ? year[1] : '', function (err, film) {
                if (!page.alive()) return;
                if (err || !film) { finish(); return; }
                filmImdb = film.imdb_id || null;   // so a film seen to the end leaves "Chci vidět"
                var hadFocus = filmBox.contains(document.activeElement);
                filmBox.textContent = '';
                filmSide(filmBox, film, title, q, params.imdb_id, false);
                if (hadFocus) Nav.focus(filmBox.querySelector('.hc-back'));
                if (film.scene || film.backdrop) {
                    bg.appendChild(el('img', 'hc-detail-bg__art', null, {src: film.scene || film.backdrop, alt: ''}));
                }
                bg.appendChild(el('div', 'hc-detail-bg__shade'));

                if (!fitOpts.year && film.year) fitOpts.year = +film.year;
                var known = names.map(StreamInfo.normalize);
                [film.title, film.original_title].forEach(function (name) {
                    if (!name || known.indexOf(StreamInfo.normalize(name)) >= 0) return;
                    known.push(StreamInfo.normalize(name));
                    names.push(name);
                    StreamInfo.searchVariants(name, fitOpts.year).forEach(search);
                });
                finish();
            });

            function say(text) {
                status.textContent = text;
                status.style.display = '';
            }

            var drawn = false;        // a list is on screen
            var firstFocus = null;    // what the first drawing focused
            var filterKey = 'all';    // the filter the viewer picked
            function shown(err, files, final) {
                if (!page.alive()) return;
                if (!final && (drawn || !files.length)) return;
                files = files.slice();
                if (files.length) err = null;
                if (err || !files.length) {
                    say(err ? 'Hledání se nepovedlo: ' + err.message : 'Na Webshare se pro „' + title + '“ nenašel žádný soubor.');
                    var again = add(el('a', 'hc-btn', null, {href: '#/search', 'data-autofocus': ''}), el('span', null, 'ZKUSIT HLEDÁNÍ'));
                    add(streams, add(el('div', 'hc-detail__actions'), again));
                    page.ready();
                    return;
                }
                // Files of this film first, then the rest; largest first in each
                files.forEach(function (file) { file.fit = StreamInfo.relevance(file, names, fitOpts) > 0; });
                var fitting = files.filter(function (file) { return file.fit; }).length;
                // An early list only when it already has this film's files
                if (!final && !fitting) return;
                files.sort(function (a, b) { return (b.fit - a.fit) || (b.size - a.size); });
                files.forEach(function (file) { file.info = StreamInfo.describe(file.name, file.size); file.recommended = false; });
                var infos = files.map(function (file) { return file.info; });
                var fits = files.map(function (file) { return file.fit; });

                // Drawn again: remember where the viewer is, to stay there
                var before = document.activeElement;
                var onIdent = before && list.contains(before) ? before.getAttribute('data-ident') : null;
                var onFilter = before && filters.contains(before) ? before.getAttribute('data-filter') : null;
                var untouched = !drawn || before === firstFocus || before === document.body || !before;
                list.textContent = '';
                filters.textContent = '';
                // Nothing fits the name: rather show everything than nothing
                if (!fitting) fits = fits.map(function () { return true; });
                var best = StreamInfo.pickRecommended(infos.slice(0, fitting || infos.length));
                if (best >= 0) files[best].recommended = true;
                // Start on the recommended file only when it is on the first
                // screen, so the page never opens scrolled down
                var start = best >= 0 && best < 6 ? best : 0;

                var rows = files.map(function (file, i) {
                    var row = streamRow(file, i, title);
                    row.setAttribute('data-ident', file.ident);
                    if (i === start) row.setAttribute('data-autofocus', '');
                    row.addEventListener('click', function (e) {
                        e.preventDefault();
                        Player.play({ident: file.ident, name: file.name, title: title, q: q,
                                     info: file.info.res + ' · ' + file.info.label, imdb_id: params.imdb_id || filmImdb,
                                     show: params.show},
                            function (message) { say('Nejde přehrát: ' + message); });
                    });
                    list.appendChild(row);
                    return row;
                });

                // 'other' = files whose name does not fit this film; the
                // other filters only look at the files that do fit
                function matches(i, key) {
                    var info = infos[i];
                    if (key === 'other') return !fits[i];
                    if (!fits[i]) return false;
                    if (key === 'all') return true;
                    if (key === 'tv') return info.tv_ok;
                    if (key === 'cz') return info.language !== 'EN';
                    return info.res === key;
                }
                var buttons = [];
                function apply(key) {
                    var shown = 0;
                    rows.forEach(function (row, i) {
                        var ok = matches(i, key);
                        row.style.display = ok ? '' : 'none';
                        if (ok) shown += 1;
                    });
                    buttons.forEach(function (b) { b.node.className = 'hc-filter' + (b.key === key ? ' is-on' : ''); });
                    filterKey = key;
                    count.textContent = filesCount(shown) + (final ? '' : ' · HLEDÁM DALŠÍ…');
                    status.style.display = 'none';
                    if (!fitting) say('Žádný soubor přesně neodpovídá názvu, ukazuji všechno, co Webshare našel.');
                }
                // Only offer filters that match something
                var good = infos.filter(function (s, i) { return fits[i]; });
                var offer = [{key: 'all', label: 'VŠE'}];
                ['4K', '1080P', '720P'].forEach(function (res) {
                    if (good.some(function (s) { return s.res === res; })) offer.push({key: res, label: res});
                });
                if (good.some(function (s) { return s.language !== 'EN'; })) offer.push({key: 'cz', label: 'CZ / SK'});
                if (good.some(function (s) { return s.tv_ok; })) offer.push({key: 'tv', label: 'PŘEHRAJE TV'});
                var others = files.length - good.length;
                if (others) offer.push({key: 'other', label: 'OSTATNÍ ' + others});
                if (offer.length > 1) {
                    offer.forEach(function (f) {
                        var node = el('button', 'hc-filter', f.label, {type: 'button', 'data-filter': f.key});
                        node.addEventListener('click', function () { apply(f.key); });
                        buttons.push({key: f.key, node: node});
                        filters.appendChild(node);
                    });
                }
                apply(offer.some(function (f) { return f.key === filterKey; }) && offer.length > 1 ? filterKey : 'all');
                note.style.display = '';
                // The recommended file below the screen's edge: start at the
                // top instead, so the page never opens scrolled down
                if (rows[start] && start > 0 && rows[start].getBoundingClientRect().bottom > window.innerHeight) {
                    rows[start].removeAttribute('data-autofocus');
                    rows[0].setAttribute('data-autofocus', '');
                }
                drawn = true;
                if (untouched) {
                    page.ready();
                    firstFocus = document.activeElement;
                    return;
                }
                // The viewer moved meanwhile: the same file or filter again
                var back = null;
                rows.forEach(function (row) { if (onIdent && row.getAttribute('data-ident') === onIdent) back = row; });
                buttons.forEach(function (b) { if (onFilter && b.key === onFilter) back = b.node; });
                if (back && back.offsetParent !== null) Nav.focus(back);
                else if (onIdent || onFilter) page.ready();
            }
        }
    });
})();

// Screens for finding something to watch: search with an on-screen keyboard,
