    // Plays one episode: the saved position, or the best fitting file from
    // Webshare; without one the list of files opens. note(text) shows progress.
    function playEpisode(show, season, episode, resume, page, note) {
        if (resume) {
            Player.play({ident: resume.ident, name: resume.name || resume.title || '', title: resume.title,
                         info: resume.info, imdb_id: resume.imdb_id, q: resume.q, show: resume.show}, function (message) {
                note('NEJDE PŘEHRÁT: ' + message);
            });
            return;
        }
        note('HLEDÁM ' + Series.label(season, episode) + ' NA WEBSHARE…');
        Player.findEpisode(show, season, episode, lastFileOf(show.tmdb_id), show.imdb_id, function (found) {
            if (!page.alive()) return;
            note('');
            if (!found.what) { App.go(url('files', found.files)); return; }
            Player.play(found.what, function () { App.go(url('files', found.files)); });
        });
    }

    // Which language the files of an episode on Webshare have:
    // 'CZ', 'SK', 'EN' or 'NONE'. Remembered for 12 hours.
    var langQueue = [];
    var langRunning = 0;
    function episodeLang(show, season, episode, alive, done) {
        var key = 'eplang:' + show.tmdb_id + ':' + season + ':' + episode;
        var hit = Store.Cache.get(key);
        if (hit) { done(hit); return; }
        langQueue.push(function (finish) {
            if (!alive()) { finish(); return; }
            var code = Series.label(season, episode);
            var names = [show.title, show.original_title].filter(Boolean);
            var queries = [show.title + ' ' + code];
            if (show.original_title && show.original_title.toLowerCase() !== show.title.toLowerCase()) {
                queries.push(show.original_title + ' ' + code);
            }
            var best = 'NONE';
            var rank = {NONE: 0, EN: 1, SK: 2, CZ: 3};
            function next(i) {
                if (i >= queries.length || best === 'CZ') {
                    Store.Cache.set(key, best, 12 * 3600);
                    finish();
                    done(best);
                    return;
                }
                Webshare.search(queries[i], Store.Token.get(), 30, function (err, files) {
                    if (err) { finish(); done(''); return; }   // not remembered: may work next time
                    files.forEach(function (f) {
                        if (!StreamInfo.relevance(f, names, {season: season, episode: episode})) return;
                        var lang = StreamInfo.describe(f.name, f.size).language;
                        if (rank[lang] > rank[best]) best = lang;
                    });
                    next(i + 1);
                });
            }
            next(0);
        });
        pumpLang();
    }
    function pumpLang() {
        while (langRunning < 2 && langQueue.length) {
            langRunning += 1;
            langQueue.shift()(function () { langRunning -= 1; pumpLang(); });
