                left.appendChild(bigTitle(title));
                add(right, head('EPIZODY'),
                    el('p', 'hc-pick-empty', 'Seriál „' + title + '“ se v databázi nenašel. Zkuste ho vyhledat přímo v souborech.'),
                    add(el('div', 'hc-detail__actions'),
                        add(el('a', 'hc-btn', null, {href: url('files', {q: title, title: title}), 'data-autofocus': ''}),
