                    if (f[1]) add(facts, add(el('div'), el('dt', null, f[0]), el('dd', null, String(f[1]))));
                });
                var st = Series.status(show);
                add(left, add(top, facts), bigTitle(show.title),
                    st.text ? el('span', 'hc-show-status hc-show-status--' + st.kind, st.text) : null);

                // Continue where the viewer left off, or start from the first episode
                var c = me ? Series.card(me, show) : null;
                var first = show.seasons.filter(function (s) { return s.number > 0; })[0] || show.seasons[0];
                var go = c && !c.finished ? c : (!me && first ? {season: first.number, episode: 1, resume: null,
                                                                   line: 'ZAČÍT ' + Series.label(first.number, 1)} : null);
                if (go) {
                    var button = el('button', 'hc-btn', null, {type: 'button'});
                    button.innerHTML = ICON_PLAY;   // constant icon
                    var text = el('span', null, go.line);
                    button.appendChild(text);
                    var line = el('span', 'hc-show-go__note', c && c.badge ? c.badge : '');
                    button.addEventListener('click', function () {
                        playEpisode(show, go.season, go.episode, go.resume, page, function (t) {
                            line.textContent = t || (c && c.badge) || '';
                        });
                    });
                    if (c) { button.setAttribute('data-autofocus', ''); focusLeft = true; }
                    add(left, add(el('div', 'hc-show-go'), button, line));
                } else if (c && c.finished) {
                    add(left, add(el('div', 'hc-show-go'), el('span', 'hc-show-go__done', c.line === 'DOKOUKÁNO' ? c.line : 'VŠE VIDĚNO')));
                }
                left.appendChild(add(el('div', 'hc-show-want'), App.wantButton({key: 'tv:' + show.tmdb_id, kind: 'tv',
                    show: String(show.tmdb_id), title: show.title, poster: show.poster, imdb_id: show.imdb_id})));
                if (show.overview) left.appendChild(el('p', 'hc-detail__plot', show.overview));
                App.crewList(left, show.creator_person ? {id: show.creator_person.id, name: show.creator_person.name, job: 'TVŮRCE'} : null, show.cast);
                var art = show.scene || show.backdrop;
                if (art) bg.appendChild(el('img', 'hc-detail-bg__art', null, {src: art, alt: ''}));
                bg.appendChild(el('div', 'hc-detail-bg__shade'));
            }

            function seasonName(number) { return number === 0 ? 'SPECIÁLY' : 'ŘADA ' + number; }

            function episodeRow(show, number, e, resume) {
                var code = Series.label(number, e.number);
                var out = e.iso ? Series.aired(e.iso, Date.now()) : Series.isOut(show, number, e.number);
                var state = Series.state(me, number, e.number);
                var row = el('a', 'hc-stream hc-ep' + (out ? '' : ' is-future'), null, {
                    href: App.episodeLink(show, number, e.number)
                });
                // Left half way: OK continues from the saved position
                if (resume) {
                    row.addEventListener('click', function (ev) {
                        ev.preventDefault();
                        playEpisode(show, number, e.number, resume, page, function () {});
                    });
                }
                var still = el('span', 'hc-ep__still');
                if (e.still && safePoster(e.still)) still.appendChild(App.lazyImg(null, e.still));
                else still.appendChild(el('span', 'hc-ep__blank', 'E' + two(e.number)));
                if (state) still.appendChild(seenBadge(state));
                if (resume && resume.progress) {
                    var fill = el('i');
                    fill.style.width = resume.progress + '%';
                    still.appendChild(add(el('span', 'hc-ep__bar'), fill));
                }
                var tags = el('span', 'hc-ep__tags');
                if (!out) tags.appendChild(el('span', 'is-future', e.iso ? 'VYJDE ' + Series.dateText(e.iso) : 'ZATÍM NEVYŠLO'));
                var meta = code + (e.date ? ' · ' + e.date : '') + (e.runtime ? ' · ' + e.runtime + ' MIN' : '');
                add(row, add(el('span', 'hc-frame'), add(el('span', 'hc-frame__in hc-ep__in'),
                    still,
                    add(el('span', 'hc-ep__main'),
                        el('span', 'hc-ep__name', 'E' + two(e.number) + ' · ' + e.name),
                        el('span', 'hc-ep__meta', meta),
                        e.overview ? el('span', 'hc-ep__plot', e.overview) : null,
                        tags))));
                return {row: row, out: out, tags: tags};
            }

            // first = the screen has just opened (focus goes where the app decides)
            function drawSeason(show, number, first) {
                seasonOf[show.tmdb_id] = number;
                Tmdb.season(show.tmdb_id, number, function (err, episodes) {
                    if (!page.alive()) return;
                    episodes = err ? [] : episodes;
                    right.textContent = '';
                    var p = me ? Series.seasonProgress(me, number, episodes.length) : null;
                    add(right, head(seasonName(number), episodes.length ? plural(episodes.length, 'EPIZODA', 'EPIZODY', 'EPIZOD') : '',
                        p && p.done ? 'VIDĚNO ' + p.done + ' Z ' + p.total : ''));
                    var current = null;
                    if (show.seasons.length > 1) {
                        var filters = el('div', 'hc-filters hc-filters--wrap');
                        show.seasons.forEach(function (s) {
                            var all = me && Series.seasonProgress(me, s.number, s.episodes).done === s.episodes;
                            var b = el('button', 'hc-filter' + (s.number === number ? ' is-on' : ''),
                                (all ? '✓ ' : '') + seasonName(s.number), {type: 'button'});
                            b.addEventListener('click', function () { if (s.number !== number) drawSeason(show, s.number, false); });
                            if (s.number === number) current = b;
                            filters.appendChild(b);
                        });
                        right.appendChild(filters);
                    }
                    if (!episodes.length) {
                        right.appendChild(el('p', 'hc-pick-empty', 'K této řadě se nepodařilo načíst seznam epizod.'));
                    } else {
                        var list = el('div', 'hc-streams hc-episodes');
                        var up = me ? Series.upNext(me, show.seasons) : null;
                        var rows = [];
                        episodes.forEach(function (e, i) {
                            var resume = me && me.resume && me.last.season === number && me.last.episode === e.number ? me.resume : null;
                            var made = episodeRow(show, number, e, resume);
                            var isUp = up && up.season === number && up.episode === e.number;
                            if (!focusLeft && (isUp || (i === 0 && !(up && up.season === number)))) made.row.setAttribute('data-autofocus', '');
                            list.appendChild(made.row);
                            rows.push({e: e, made: made});
                        });
                        right.appendChild(list);
                        // Language of the files on Webshare, episode by episode
                        rows.forEach(function (r) {
                            if (!r.made.out) return;
                            episodeLang(show, number, r.e.number, page.alive, function (lang) {
                                if (!lang || !page.alive() || seasonOf[show.tmdb_id] !== number) return;
                                r.made.tags.appendChild(el('span', 'hc-ep__lang hc-ep__lang--' + lang.toLowerCase(), LANG_TEXT[lang]));
                            });
                        });
                    }
                    if (first) page.ready();
                    else { window.scrollTo(0, 0); Nav.focus(current); }
                });
            }

            function similar(show) {
                Tmdb.similarShows(show.tmdb_id, function (err, list) {
                    if (err || !list.length || !page.alive()) return;
                    view.appendChild(add(el('div', 'hc-show-more'), rowSection('PODOBNÉ SERIÁLY', '', list.slice(0, 16))));
                });
            }

            function load(id) {
                Tmdb.show(id, function (err, show) {
                    if (!page.alive()) return;
                    if (err || !show) { notFound(); return; }
                    me = Series.find(Series.fromStore(), id);
                    drawLeft(show);
                    if (!show.seasons.length) {
                        add(right, head('EPIZODY'), el('p', 'hc-pick-empty', 'U tohoto seriálu nejsou v databázi žádné řady.'));
                        page.ready();
                        return;
                    }
                    var up = me ? Series.upNext(me, show.seasons) : null;
                    var wanted = seasonOf[id] !== undefined ? seasonOf[id] : (up ? up.season : (me ? me.last.season : null));
                    var known = show.seasons.some(function (s) { return s.number === wanted; });
                    drawSeason(show, known ? wanted : show.seasons[0].number, true);
                    similar(show);
                });
            }

            if (params.tmdb_id) load(+params.tmdb_id);
            else Tmdb.findShow(params.imdb_id, params.title, function (err, id) {
                if (!page.alive()) return;
                if (id) load(id); else notFound();
            });
        }
    });

    // ------------------------------------------------------------ person
    var personView = {};   // person id -> {filter, order, opened}, kept for Back

    App.screen('person', {
        header: false,
        bare: true,
        nav: 'search',
        render: function (params, view, page) {
            var id = +params.id;
            var state = personView[id] || (personView[id] = {filter: 'all', order: 'known', opened: ''});
            var bg = el('div', 'hc-detail-bg');
            page.backdrop.appendChild(bg);
            var left = add(el('section', 'hc-detail__film'), backLink('ZPĚT'));
            var right = el('section', 'hc-detail__streams');
            add(view, add(el('div', 'hc-detail hc-person-page'), left, right));

            function drawLeft(p) {
                var top = el('div', 'hc-detail__top');
                if (safePoster(p.photo)) add(top, add(el('span', 'hc-detail__poster'), el('img', null, null, {src: p.photo, alt: ''})));
                var facts = el('dl', 'hc-facts');
                [['OBOR', p.dept], ['NAROZENÍ', p.born], ['MÍSTO', p.place], ['ÚMRTÍ', p.died]].forEach(function (f) {
                    if (f[1]) add(facts, add(el('div'), el('dt', null, f[0]), el('dd', null, String(f[1]))));
                });
                var name = p.name.length > 16 ? ' hc-detail__title--s' : (p.name.length > 8 ? ' hc-detail__title--m' : '');
                var bio = el('p', 'hc-detail__plot', p.bio);
                bio.style.display = p.bio ? '' : 'none';
                add(left, add(top, facts), el('h1', 'hc-detail__title' + name, p.name), bio);
                if (!p.bio) Tmdb.personBio(id, function (err, text) {
                    if (err || !text || !page.alive()) return;
                    bio.textContent = text;
                    bio.style.display = '';
                });
                if (p.known_for) Tmdb.backdropOf(p.known_for.kind, p.known_for.id, function (err, art) {
                    if (err || !art || !page.alive()) return;
                    add(bg, el('img', 'hc-detail-bg__art', null, {src: art, alt: ''}), el('div', 'hc-detail-bg__shade'));
                });
            }

            function drawRight(p) {
                var count = el('span', 'hc-pick-head__count');
                var filters = el('div', 'hc-filters hc-filters--wrap');
                var grid = el('div', 'hc-grid hc-person__grid');
                var empty = el('p', 'hc-pick-empty', 'K tomuto člověku databáze nezná žádné filmy ani seriály.');
                add(right, add(el('div', 'hc-pick-head'),
                    add(el('div'), el('span', 'hc-kicker', '// FILMOGRAFIE'), el('h2', null, 'FILMY A SERIÁLY')), count),
                    filters, grid, empty);

                var kinds = [['all', 'VŠE'], ['movie', 'FILMY'], ['tv', 'SERIÁLY'], ['directed', 'REŽIE']];
                function matches(c, which) {
                    if (which === 'all') return true;
                    if (which === 'directed') return c.directed;
                    return c.kind === which;
                }
                var buttons = [];
                kinds.forEach(function (k) {
                    var n = p.credits.filter(function (c) { return matches(c, k[0]); }).length;
                    if (!n || (k[0] !== 'all' && n === p.credits.length)) return;
                    var b = el('button', 'hc-filter', k[1] + ' ' + n, {type: 'button'});
                    b.addEventListener('click', function () { state.filter = k[0]; draw(); });
                    buttons.push([k[0], b]);
                    filters.appendChild(b);
                });
                var order = el('button', 'hc-filter', '', {type: 'button'});
                order.addEventListener('click', function () { state.order = state.order === 'known' ? 'new' : 'known'; draw(); });
                filters.appendChild(order);
                if (!buttons.some(function (b) { return b[0] === state.filter; })) state.filter = 'all';

                function draw() {
                    buttons.forEach(function (b) { b[1].className = 'hc-filter' + (b[0] === state.filter ? ' is-on' : ''); });
                    order.textContent = state.order === 'known' ? 'ŘADIT: NEJZNÁMĚJŠÍ' : 'ŘADIT: NEJNOVĚJŠÍ';
                    var list = p.credits.filter(function (c) { return matches(c, state.filter); });
                    if (state.order === 'new') {
                        // Not yet released (no year) first, then newest
                        list = list.slice().sort(function (a, b) { return (+b.year || 9999) - (+a.year || 9999); });
                    }
                    grid.textContent = '';
                    list.forEach(function (c) {
                        var made = posterCard(c, c.title + (c.year ? ' · ' + c.year : ''));
                        var role = c.roles.filter(Boolean).join(' · ');
                        if (role) made.box.appendChild(el('span', 'hc-sres__role', role));
                        if (c.kind === 'tv') made.box.querySelector('.hc-sres__title').textContent = 'SERIÁL · ' + c.title + (c.year ? ' · ' + c.year : '');
                        made.link.addEventListener('click', function () { state.opened = made.link.getAttribute('href'); });
                        grid.appendChild(made.box);
                    });
                    count.textContent = plural(list.length, 'TITUL', 'TITULY', 'TITULŮ');
                    empty.style.display = p.credits.length ? 'none' : '';
                }
                draw();

                // Back from a film: return to it; otherwise start on the first poster
                var links = grid.querySelectorAll('a');
                for (var i = 0; i < links.length; i++) {
                    if (page.back && links[i].getAttribute('href') === state.opened) { Nav.focus(links[i]); return; }
                }
                if (links[0]) links[0].setAttribute('data-autofocus', '');
                page.ready();
            }

            Tmdb.person(id, function (err, p) {
                if (!page.alive()) return;
                if (err || !p) {
                    add(left, el('h1', 'hc-detail__title hc-detail__title--m', 'NENAČTENO'));
                    right.appendChild(el('p', 'hc-pick-empty', 'Údaje o tomto člověku se nepodařilo načíst. Zkuste to za chvíli znovu.'));
                    page.ready();
                    return;
                }
                drawLeft(p);
                drawRight(p);
            });
        }
    });

