    // Series like the ones the viewer watches, best matches first
    function tvTips(done) {
        var mine = Series.fromStore().slice(0, 5);
        if (!mine.length) { done(null, []); return; }
        var lists = [];
        var left = mine.length;
        var own = {};
        mine.forEach(function (m) { own[m.show] = true; });
        mine.forEach(function (m, i) {
            Tmdb.similarShows(+m.show, function (err, list) {
                lists[i] = err ? [] : list;
                if (--left) return;
                var out = [], seen = {};
                for (var k = 0; k < 20; k++) {
                    lists.forEach(function (l) {
                        var item = l[k];
                        if (!item || own[item.tmdb_id] || seen[item.tmdb_id]) return;
                        seen[item.tmdb_id] = true;
                        out.push(item);
                    });
                }
                done(null, out.slice(0, 40));
            });
        });
    }

    // "My series": where the viewer is in each one, the next episode, new ones
    function myShowsSection(page) {
        var list = Series.fromStore().slice(0, 20);
        if (!list.length) return null;
        var row = el('div', 'hc-row');
        var history = Store.History.all();
        list.forEach(function (me) {
            var name = '';
            var from = me.resume || null;
            for (var i = 0; !from && i < history.length; i++) if (String(history[i].show) === me.show) from = history[i];
            if (from) name = (from.title || '').replace(/\s*S\d{1,2}E\d{1,3}.*$/i, '');
            var title = el('span', 'hc-cont__title', name || 'SERIÁL');
            var badge = el('span', 'hc-myshow__badge');
            var panel = add(el('span', 'hc-cont__panel'), badge, title);
            var line = el('span', 'hc-cont__left', Series.label(me.last.season, me.last.episode));
            var card = add(el('a', 'hc-cont hc-myshow', null, {href: url('show', {tmdb_id: me.show})}),
                add(el('span', 'hc-frame'), add(el('span', 'hc-frame__in'), panel)), line);
            row.appendChild(card);
            Tmdb.show(+me.show, function (err, show) {
                if (err || !show || !page.alive()) return;
                title.textContent = show.title;
                var art = show.backdrop || show.poster;
                if (art) {
                    panel.insertBefore(el('span', 'hc-cont__shade'), panel.firstChild);
                    panel.insertBefore(App.lazyImg('hc-cont__art', art.replace('/w1280/', '/w780/')), panel.firstChild);
                }
                var c = Series.card(me, show);
                line.textContent = c.line;
                if (c.badge) { badge.textContent = c.badge; badge.className = 'hc-myshow__badge is-on'; }
                if (c.again && c.resume && c.resume.progress) {
                    var fill = el('i');
                    fill.style.width = c.resume.progress + '%';
                    panel.appendChild(add(el('span', 'hc-cont__bar'), fill));
                }
                // Seen to the end: to the back of the row (not the card with the focus)
                if (c.finished) {
                    card.className += ' is-finished';
                    if (document.activeElement !== card) row.appendChild(card);
                }
            });
        });
        return add(el('section', 'hc-section hc-myshows'),
            add(el('div', 'hc-section__head'), el('span', 'hc-section__bar'), el('h2', 'hc-section__title', 'MOJE SERIÁLY'),
                el('span', 'hc-section__count', two(list.length))),
            row);
    }
