                view.appendChild(mine);
            }
            var tipsPlace = el('div');
            view.appendChild(tipsPlace);
            add(view,
                tileGroup('PROCHÁZET', [
                    {href: url('list', {id: 'tv-trending'}), art: 'tv-trending', name: 'Trendy seriály', sub: 'TMDB · TENTO TÝDEN'},
                    {href: url('list', {id: 'tv-top'}), art: 'tv-top', name: 'Nejlépe hodnocené', sub: 'TMDB · NEJVYŠŠÍ HODNOCENÍ'},
                    {href: url('list', {id: 'tv-csfd'}), art: 'tv-csfd', name: 'ČSFD Top seriály', sub: 'ČSFD · TOP 100'},
                    {href: url('list', {id: 'tv-czech'}), art: 'tv-czech', name: 'České a slovenské', sub: 'OD ARABELY PO MOST!'},
                    {href: url('list', {id: 'tv-mini'}), art: 'tv-mini', name: 'Minisérie na víkend', sub: 'JEDNA ŘADA A KONEC'},
                    {href: '#/search', art: 'search', name: 'Hledat seriál', sub: 'KLÁVESNICE NA OBRAZOVCE'}
                ], !mine),
                tileGroup('PODLE ŽÁNRU', TV_GENRES.map(function (g) {
                    return {href: url('list', {id: 'tv-g' + g.id}), art: 'tv-g' + g.id, name: g.name, sub: 'NEJZNÁMĚJŠÍ SERIÁLY'};
                })),
                tileGroup('PODLE SLUŽBY', TV_NETWORKS.map(function (n) {
                    return {href: url('list', {id: 'tv-n-' + n.key}), art: 'tv-n-' + n.key, name: n.name, sub: 'PRÁVĚ OBLÍBENÉ'};
                })));
            page.ready();
            if (mine) {
                tvTips(function (err, list) {
                    if (err || !list.length || !page.alive()) return;
                    var section = rowSection('TIPY NA SERIÁLY', '', list.slice(0, 20));
                    section.querySelector('.hc-section__head').appendChild(
                        el('a', 'hc-section__more', 'VŠECHNY TIPY', {href: url('list', {id: 'tv-tips'})}));
                    tipsPlace.appendChild(section);
                });
            }
        }
    });

    // ------------------------------------------------------------ collections
    var ICON_CHECK = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
    var ICON_PLAY = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4.5v15l12.5-7.5z"/></svg>';

    function filmsCount(n) { return plural(n, 'FILM', 'FILMY', 'FILMŮ'); }

    function seenText(p) {
        return p.done ? 'VIDĚNO ' + p.done + ' Z ' + p.total : '';
    }

    // Wide tile with a picture, name, description and what was seen
    function collectionTile(item) {
        var meta = el('span', 'hc-col__meta', item.discover ? 'SAMO SE DOPLŇUJE' : filmsCount(item.count || 0));
        var bar = el('span', 'hc-col__bar');
        var panel = add(el('span', 'hc-frame__in hc-col__in'),
            item.art && safePoster(item.art) ? App.lazyImg('hc-col__art', item.art) : null,
            el('span', 'hc-col__shade'),
            add(el('span', 'hc-col__text'),
                el('span', 'hc-col__name', item.name),
                el('span', 'hc-col__desc', item.desc || ''),
                meta),
            bar);
        var tile = add(el('a', 'hc-frame hc-col', null, {href: url('list', {id: 'col-' + item.id}), 'aria-label': item.name}), panel);
        return {tile: tile, seen: function (p) {
            if (!p.done) return;
            meta.textContent = filmsCount(p.total) + ' · ' + seenText(p);
            meta.className = 'hc-col__meta hc-col__meta--seen';
            var fill = el('i');
            fill.style.width = Math.round(p.done / p.total * 100) + '%';
            bar.appendChild(fill);
        }};
    }

    App.screen('collections', {
        render: function (params, view, page) {
            view.appendChild(add(el('div', 'app-loading'), el('span', 'hc-kicker', '// NAČÍTÁM KOLEKCE…')));
            Collections.index(function (err, groups) {
                if (!page.alive()) return;
                view.textContent = '';
                add(view, add(el('div', 'hc-page-head'), el('span', 'hc-kicker', '// ARCHIV · KOLEKCE'), el('h1', null, 'KOLEKCE')));
                if (err) {
                    add(view, el('p', 'hc-empty', 'Kolekce se teď nepodařilo načíst. Zkuste to za chvíli znovu.'),
                        add(el('div', 'hc-list__tools'), backLink('ZPĚT')));
                    page.ready();
                    return;
                }
                var seen = Collections.fromStore();
                var waiting = [];
                groups.forEach(function (group, g) {
                    var row = el('div', 'hc-row hc-colrow');
                    group.items.forEach(function (item, i) {
                        var made = collectionTile(item);
                        if (g === 0 && i === 0) made.tile.setAttribute('data-autofocus', '');
                        row.appendChild(made.tile);
                        if (item.file) waiting.push({file: item.file, seen: made.seen});
                    });
                    view.appendChild(add(el('section', 'hc-colgroup'),
                        add(el('div', 'hc-section__head'), el('span', 'hc-section__bar'),
                            el('h2', 'hc-section__title', group.name.toUpperCase()),
                            el('span', 'hc-section__count', plural(group.items.length, 'KOLEKCE', 'KOLEKCE', 'KOLEKCÍ'))),
                        row));
                });
                page.ready();
                // What was seen of each list, a few files at a time
                function nextFile() {
                    var job = waiting.shift();
                    if (!job || !page.alive()) return;
                    Collections.getJson(job.file, function (err2, films) {
                        if (!err2 && films instanceof Array && page.alive()) job.seen(Collections.progress(films, seen));
                        nextFile();
                    });
                }
                for (var n = 0; n < 4; n++) nextFile();
            });
        }
    });

    // ------------------------------------------------------------ one list
    function listFile(file, done) {
        Collections.getJson(file, function (err, data) {
            if (!err && !(data instanceof Array)) err = new Error('seznam není dostupný');
            done(err, err ? null : data);
        });
    }

    // Where a list comes from: done(def) or done(null) when unknown
    function listDef(id, done) {
        if (LISTS[id]) { done(LISTS[id]); return; }
        if (id.indexOf('col-') !== 0) { done(null); return; }
        Collections.index(function (err, groups) {
            var item = err ? null : Collections.find(groups, id.slice(4));
            done(item ? {name: item.name.toUpperCase(), kind: 'movie', file: item.file, nav: 'collections', col: item} : null);
        });
    }

    function seenBadge(state) {
        if (!state) return null;
        var badge = el('span', 'hc-seen hc-seen--' + state);
        if (state === 'done') badge.innerHTML = ICON_CHECK;   // constant icon
        badge.appendChild(el('span', null, state === 'done' ? 'VIDĚNO' : 'ROZKOUKÁNO'));
        return badge;
    }

    App.screen('list', {
        nav: function (params) {
            if ((params.id || '').indexOf('col-') === 0) return 'collections';
            var def = LISTS[params.id];
            return def ? (def.nav || (def.kind === 'tv' ? 'series' : 'movies')) : 'movies';
        },
        render: function (params, view, page) {
            var pageNo = Math.max(1, parseInt(params.page, 10) || 1);
            view.appendChild(add(el('div', 'app-loading'), el('span', 'hc-kicker', '// NAČÍTÁM SEZNAM…')));
            listDef(params.id || '', function (def) {
                if (!page.alive()) return;
                if (!def) { App.go('#/movies', true); return; }
                var col = def.col;
                var story = !!(col && col.story && params.order === 'story');
                var kicker = '// ARCHIV · ' + (def.nav === 'collections' ? 'KOLEKCE' : (def.kind === 'tv' ? 'SERIÁLY' : 'FILMY'));

                function draw(err, all) {
                    if (!page.alive()) return;
                    view.textContent = '';
                    all = err ? [] : (col ? Collections.ordered(all, story) : all);
                    var pages = Math.ceil(all.length / PER_PAGE);
                    pageNo = Math.min(pageNo, Math.max(1, pages));
                    view.appendChild(pageHead(kicker, def.name,
                        pages > 1 ? el('span', 'hc-page-head__count', 'STRANA ' + two(pageNo) + ' / ' + two(pages)) : null));
                    if (!all.length) {
                        add(view, el('p', 'hc-empty', 'Seznam se teď nepodařilo načíst nebo je prázdný. Zkuste to za chvíli znovu.'),
                            add(el('div', 'hc-list__tools'), backLink('ZPĚT')));
                        page.ready();
                        return;
                    }
                    var seen = col ? Collections.fromStore() : null;
                    var focusSet = false;
                    if (col) {
                        var p = Collections.progress(all, seen);
                        var tools = el('div', 'hc-colhead__tools');
                        if (col.saga && p.next) {
                            var cont = el('a', 'hc-btn', null, {href: titleUrl({kind: 'movie', title: p.next.title, year: p.next.year,
                                                                               imdb_id: p.next.imdb_id})});
                            cont.innerHTML = ICON_PLAY;   // constant icon
                            cont.appendChild(el('span', null, (p.done ? 'POKRAČOVAT: ' : 'ZAČÍT: ') + p.next.title));
                            cont.setAttribute('data-autofocus', '');
                            focusSet = true;
                            tools.appendChild(cont);
                        }
                        if (col.story) {
                            // Two buttons; the order shown now carries a tick
                            var orderButton = function (label, value, on) {
                                var b = el('button', 'hc-btn hc-btn--ghost' + (on ? ' is-on' : ''), null, {type: 'button'});
                                if (on) b.innerHTML = ICON_CHECK;   // constant icon
                                b.appendChild(el('span', null, label));
                                b.addEventListener('click', function () {
                                    if (!on) App.go(url('list', {id: params.id, order: value}), true);
                                });
                                return b;
                            };
                            tools.appendChild(orderButton('JAK ŠLY DO KIN', 'release', !story));
                            tools.appendChild(orderButton('PODLE PŘÍBĚHU', 'story', story));
                        }
                        var line = col.discover ? 'SEZNAM SE SÁM DOPLŇUJE O NOVÉ FILMY' : filmsCount(all.length);
                        if (p.done) line += ' · ' + seenText(p);
                        add(view, add(el('div', 'hc-colhead'),
                            el('p', 'hc-colhead__desc', col.desc || ''),
                            el('span', 'hc-colhead__meta' + (p.done ? ' hc-colhead__meta--seen' : ''), line),
                            tools.childNodes.length ? tools : null));
                    }
                    var grid = el('div', 'hc-grid');
                    var first = (pageNo - 1) * PER_PAGE;
                    all.slice(first, pageNo * PER_PAGE).forEach(function (item, i) {
                        var entry = {kind: def.kind, title: item.title, year: item.year, imdb_id: item.imdb_id,
                                     tmdb_id: item.tmdb_id, poster: item.poster, search_query: item.search_query,
                                     rating: item.rating, votes: item.votes};
                        var caption = col && col.saga ? two(first + i + 1) + ' · ' + item.title + (item.year ? ' · ' + item.year : '') : null;
                        var made = posterCard(entry, caption);
                        if (seen) add(made.box.querySelector('.hc-poster-wrap'), seenBadge(Collections.state(item, seen)));
                        if (item.note) made.box.appendChild(el('span', 'hc-sres__role', item.note));
                        if (i === 0 && !focusSet) made.link.setAttribute('data-autofocus', '');
                        grid.appendChild(made.box);
                        // Plain lists carry no pictures: ask TMDB for each one
                        if (!entry.poster) {
                            Tmdb.posterFor(entry, def.kind, function (err2, found) {
                                if (err2 || !found || !page.alive()) return;
                                if (found.poster) made.picture(found.poster);
                                if (def.kind === 'tv' && found.tmdb_id) made.link.setAttribute('href', url('show', {tmdb_id: found.tmdb_id}));
                            });
                        }
                    });
                    view.appendChild(grid);
                    if (pages > 1) {
                        var pager = el('div', 'hc-pager');
                        var turn = function (label, to) {
                            var b = add(el('button', 'hc-btn hc-btn--ghost', null, {type: 'button'}), el('span', null, label));
                            // Replaces the page, so Back leaves the list in one step
                            b.addEventListener('click', function () {
                                App.go(url('list', {id: params.id, page: to, order: params.order}), true);
                            });
                            return b;
                        };
                        add(pager, pageNo > 1 ? turn('PŘEDCHOZÍ', pageNo - 1) : null,
                            el('span', 'hc-pager__page', 'STRANA ' + pageNo),
                            pageNo < pages ? turn('DALŠÍ', pageNo + 1) : null);
                        view.appendChild(pager);
                    }
                    page.ready();
                }

                if (def.tmdb) Tmdb.titles(def.tmdb, draw);
                else if (def.tips) tvTips(draw);
                else if (def.discover) Tmdb.discover(def.discover, draw, def.kind);
                else if (col && col.discover) Tmdb.discover(col.discover, draw);
                else listFile(def.file, draw);
            });
        }
    });

    // ------------------------------------------------------------ favourites
    App.screen('favorites', {
        render: function (params, view, page) {
            var count = el('span', 'hc-page-head__count');
            var grid = el('div', 'hc-grid');
            var empty = add(el('div'),
                el('p', 'hc-empty', 'Zatím tu nic není. Film přidáte tlačítkem „+ DO OBLÍBENÝCH“ na jeho stránce s výběrem streamu. Co chcete teprve vidět, uložíte tlačítkem „+ CHCI VIDĚT“ u filmu nebo seriálu, nebo tlačítkem + u doporučeného filmu na Domů.'),
                add(el('div', 'hc-list__tools'),
                    add(el('a', 'hc-btn', null, {href: '#/movies', 'data-autofocus': ''}), el('span', null, 'VYBRAT FILM'))));
            var wantCount = el('span', 'hc-section__count');
            var wantGrid = el('div', 'hc-grid');
            var wantBox = add(el('section', 'hc-want-list'),
                add(el('div', 'hc-section__head'), el('span', 'hc-section__bar'), el('h2', 'hc-section__title', 'CHCI VIDĚT'), wantCount),
                wantGrid);
            add(view, pageHead('// PALUBNÍ DENÍK · ULOŽENÉ TITULY', 'OBLÍBENÉ', count), grid, empty, wantBox);

            function drawWant() {
                var items = Store.Want.all();
                wantGrid.textContent = '';
                items.forEach(function (item, i) {
                    var made = posterCard({kind: item.kind === 'tv' ? 'tv' : 'movie', tmdb_id: item.show, title: item.title,
                                           poster: item.poster, imdb_id: item.imdb_id,
                                           search_query: item.query || item.title}, item.title);
                    if (i === 0 && !Store.Favorites.all().length) made.link.setAttribute('data-autofocus', '');
                    var remove = el('button', 'hc-chip', 'ODEBRAT', {type: 'button', 'aria-label': 'Odebrat z Chci vidět: ' + item.title});
                    remove.addEventListener('click', function () {
                        Store.Want.remove(item.key);
                        drawWant();
                        Nav.focus(wantGrid.querySelector('.hc-poster') || grid.querySelector('.hc-poster') ||
                            empty.querySelector('.hc-btn'));
                    });
                    made.box.appendChild(remove);
                    wantGrid.appendChild(made.box);
                });
                wantBox.style.display = items.length ? '' : 'none';
                wantCount.textContent = items.length ? plural(items.length, 'TITUL', 'TITULY', 'TITULŮ') : '';
            }
            drawWant();

            function draw() {
                var items = Store.Favorites.all();
                grid.textContent = '';
                items.forEach(function (item, i) {
                    var made = posterCard({kind: 'movie', title: item.title, poster: item.poster,
                                           search_query: item.query || item.title}, item.title);
                    if (i === 0) made.link.setAttribute('data-autofocus', '');
                    var remove = el('button', 'hc-chip', 'ODEBRAT', {type: 'button', 'aria-label': 'Odebrat z oblíbených: ' + item.title});
                    remove.addEventListener('click', function () {
                        Store.Favorites.remove(item.title);
                        draw();
                        Nav.focus(grid.querySelector('.hc-poster') || empty.querySelector('.hc-btn'));
                    });
                    made.box.appendChild(remove);
                    grid.appendChild(made.box);
                });
                empty.style.display = items.length ? 'none' : '';
                count.textContent = items.length ? plural(items.length, 'TITUL', 'TITULY', 'TITULŮ') : '';
            }
            draw();
            page.ready();
        }
    });

    // ------------------------------------------------------------ history
    function clock(seconds) {
        seconds = Math.max(0, Math.floor(seconds || 0));
        var h = Math.floor(seconds / 3600);
        var m = Math.floor((seconds % 3600) / 60);
        return h > 0 ? h + ':' + two(m) + ':' + two(seconds % 60) : m + ':' + two(seconds % 60);
    }

    function day(stamp) {
        var d = new Date(stamp || 0);
        return d.getDate() + '. ' + (d.getMonth() + 1) + '. ' + d.getFullYear() + ' ' + d.getHours() + ':' + two(d.getMinutes());
    }

    App.screen('history', {
        nav: 'home',
        render: function (params, view, page) {
            var count = el('span', 'hc-page-head__count');
            var list = el('div', 'hc-streams hc-list');
            var wipe = add(el('button', 'hc-btn hc-btn--ghost', null, {type: 'button'}), el('span', null, 'VYMAZAT HISTORII'));
            var tools = add(el('div', 'hc-list__tools'), wipe);
            var empty = add(el('div'),
                el('p', 'hc-empty', 'Zatím jste nic nepustili. Všechno, co si přehrajete, se tu objeví.'),
                add(el('div', 'hc-list__tools'),
                    add(el('a', 'hc-btn', null, {href: '#/movies', 'data-autofocus': ''}), el('span', null, 'VYBRAT FILM'))));
            add(view, pageHead('// PALUBNÍ DENÍK · NAPOSLEDY PUŠTĚNÉ', 'HISTORIE', count), list, tools, empty);

            function row(item, i) {
                var left = Store.Resume.get(item.ident);
                var detail = el('span', 'hc-stream__file', day(item.watchedAt) +
                    (left ? ' · ROZKOUKÁNO ' + clock(left.position) + ' / ' + clock(left.duration) : ''));
                var link = el('a', 'hc-stream', null, {href: '#'});
                if (i === 0) link.setAttribute('data-autofocus', '');
                add(link, add(el('span', 'hc-frame'), add(el('span', 'hc-frame__in hc-stream__in'),
                    el('span', 'hc-stream__no', two(i + 1)),
                    add(el('span', 'hc-stream__main'), el('span', 'hc-stream__label', item.title || 'Bez názvu'), detail))));
                link.addEventListener('click', function (e) {
                    e.preventDefault();
                    Player.play({ident: item.ident, name: item.name || item.title || '', title: item.title,
                                 info: item.info, imdb_id: item.imdb_id, q: item.q, show: item.show},
                        function (message) { detail.textContent = 'NEJDE PŘEHRÁT: ' + message; });
                });
                return link;
            }

            function draw() {
                var items = Store.History.all();
                list.textContent = '';
                items.forEach(function (item, i) { list.appendChild(row(item, i)); });
                empty.style.display = items.length ? 'none' : '';
                tools.style.display = items.length ? '' : 'none';
                count.textContent = items.length ? plural(items.length, 'ZÁZNAM', 'ZÁZNAMY', 'ZÁZNAMŮ') : '';
            }

            // Two presses, so a slip of the remote does not wipe the list
            var armed = false;
            wipe.addEventListener('click', function () {
                if (!armed) { armed = true; wipe.firstChild.textContent = 'OPRAVDU VYMAZAT?'; return; }
                Store.History.clear();
                draw();
                Nav.focus(empty.querySelector('.hc-btn'));
            });
            wipe.addEventListener('blur', function () { armed = false; wipe.firstChild.textContent = 'VYMAZAT HISTORII'; });

            draw();
            page.ready();
        }
    });
})();
